insert into mealprep_recipes
  (id, name, emoji, meal_type, serves, total_minutes, scalable, ingredients, steps, notes)
values
('avo-feta-toast','Avo, feta & tomato toast','🥑','any',2,8,t,'[{"c": "veg", "n": "Ripe avocado", "q": 1, "u": ""}, {"c": "dairy", "n": "Feta", "q": 80, "u": "g"}, {"c": "veg", "n": "Tomato", "q": 1, "u": ""}, {"c": "bakery", "n": "Sourdough or seed bread", "q": 4, "u": "slices"}, {"c": "veg", "n": "Lemon", "q": 0.5, "u": ""}, {"c": "pantry", "n": "Olive oil", "q": 1, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 0.25, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.25, "u": "tsp"}]'::jsonb,'["Toast the bread. While it toasts, do everything else.", "Check the avocado is ripe: it should give slightly when you press near the stem. Rock hard means tomorrow, not today.", "Halve the avocado around the stone, twist the halves apart, and scoop the flesh into a bowl with a spoon.", "Add a squeeze of lemon, the salt and the pepper, and mash roughly with a fork. Leave it chunky — smooth avocado on toast is baby food.", "Dice the tomato small and crumble the feta with your fingers.", "Spread the avocado thickly on the hot toast, right to the edges.", "Scatter the tomato and feta over, drizzle with the olive oil and add one more grind of pepper."]'::jsonb,'Eight minutes, no cooking, and it counts as a real meal. A poached or fried egg on top makes it a proper breakfast.'),
('baked-eggs-spinach','Baked eggs with spinach & feta','🍳','any',4,30,t,'[{"c": "dairy", "n": "Eggs", "q": 8, "u": ""}, {"c": "veg", "n": "Baby spinach", "q": 200, "u": "g"}, {"c": "dairy", "n": "Feta", "q": 1, "u": "round"}, {"c": "pantry", "n": "Tinned tomatoes", "q": 1, "u": "tin"}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "veg", "n": "Garlic", "q": 2, "u": "cloves"}, {"c": "bakery", "n": "Bread rolls", "q": 4, "u": ""}, {"c": "pantry", "n": "Olive oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 190°C. You need an ovenproof frying pan, or a frying pan plus a baking dish to move everything into.", "Chop the onion finely and crush the garlic.", "Heat the olive oil in the pan over medium heat and cook the onion 8 minutes until soft and translucent. Add the garlic and cook 1 minute more.", "Add the tinned tomatoes, the salt and the pepper. Simmer on medium for 8 minutes, until the sauce has thickened and no longer looks watery. Watery sauce means the eggs poach into soup.", "Add the spinach a big handful at a time, stirring each lot until it has collapsed before adding the next. 200 g looks like far too much and wilts down to almost nothing.", "Make a dip in the sauce for each egg with the back of a spoon, spacing them out. Crack an egg into each one.", "Crumble the feta over the whole pan, in between the eggs.", "Bake 10 to 12 minutes. Start checking at 10. They are ready when the whites are completely set and opaque but the yolks still wobble when you shake the pan — they carry on cooking on the way to the table.", "Grind over a little more pepper and serve straight from the pan with the bread rolls for dipping."]'::jsonb,'Folate-rich spinach and protein-packed eggs — a pregnancy-friendly light dinner or weekend lunch. Wilt the spinach, crack the eggs over, bake till just set. Gentle tomato, nothing hot.'),
('boerie-roll','Boerewors roll','🌭','any',4,15,t,'[{"c": "meat", "n": "Boerewors", "q": 600, "u": "g"}, {"c": "bakery", "n": "Hot dog rolls", "q": 4, "u": ""}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "pantry", "n": "Tomato sauce", "q": 4, "u": "tbsp"}, {"c": "pantry", "n": "Mustard", "q": 2, "u": "tsp"}, {"c": "pantry", "n": "Chutney", "q": 2, "u": "tbsp"}, {"c": "pantry", "n": "Cooking oil", "q": 1, "u": "tbsp"}]'::jsonb,'["Do not separate the wors into links or prick it. The skin holds the fat in, and every hole you make lets flavour run into the pan.", "Slice the onion thinly.", "Heat the oil in a large frying pan over medium heat and start the onions off — 8 minutes, stirring occasionally, until soft and golden. Push them to one side of the pan.", "Coil the boerewors into the free side of the pan. Cook 5 minutes without touching it, until the underside is browned.", "Turn the whole coil over in one go using two spatulas or a pair of tongs. Cook another 5 minutes.", "Check it is done: cut into the thickest part and there should be no pink, and the juices should run clear. If it needs longer, turn the heat down and give it 2 minutes more a side rather than burning the outside.", "Split the rolls and warm them cut-side-down in the pan for 30 seconds — they soak up the wors fat.", "Cut the wors into roll-length pieces. Build: mustard on the roll, wors, fried onions, then tomato sauce and chutney over the top."]'::jsonb,'On the braai it is the same idea: medium coals, 5 to 6 minutes a side, turned once with tongs, never a fork.'),
('cheese-ham-omelette','Cheese & ham omelette','🍳','any',1,12,t,'[{"c": "dairy", "n": "Eggs", "q": 3, "u": ""}, {"c": "dairy", "n": "Cheddar", "q": 50, "u": "g"}, {"c": "meat", "n": "Ham", "q": 2, "u": "slices"}, {"c": "dairy", "n": "Butter", "q": 20, "u": "g"}, {"c": "spices", "n": "Salt", "q": 0.25, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.25, "u": "tsp"}]'::jsonb,'["Grate the cheese and chop the ham into small squares. Have both next to the stove before you start — an omelette gives you no time to fetch things.", "Beat the 3 eggs with the salt and pepper in a bowl until completely smooth, about 20 seconds of brisk forking.", "Put a small non-stick pan (20 cm) on medium heat and melt the butter, swirling it to coat the base and a little way up the sides.", "When the butter stops foaming, pour in the eggs all at once. They should sizzle gently, not violently.", "Wait 20 seconds. Then, using a spatula, push the set edges toward the middle and tilt the pan so the runny egg flows into the gaps. Do this all the way round, 3 or 4 times.", "When the top is still slightly wet but no longer runny — about 2 minutes in — scatter the ham and cheese over one half only.", "Fold the empty half over the filling with the spatula. Leave it 30 seconds for the cheese to melt.", "Slide it onto a plate. The outside should be pale yellow with no brown — a browned omelette has been cooked too hot."]'::jsonb,'Three eggs is one omelette. Doubling the eggs in the same pan does not make two — it makes a thick, badly cooked one. Do them one at a time.'),
('scrambled-eggs-toast','Creamy scrambled eggs on toast','🍳','any',2,10,t,'[{"c": "dairy", "n": "Eggs", "q": 5, "u": ""}, {"c": "dairy", "n": "Butter", "q": 30, "u": "g"}, {"c": "dairy", "n": "Milk", "q": 2, "u": "tbsp"}, {"c": "bakery", "n": "Bread", "q": 4, "u": "slices"}, {"c": "spices", "n": "Salt", "q": 0.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.25, "u": "tsp"}]'::jsonb,'["Crack the 5 eggs into a bowl. Add the milk, the salt and the pepper and beat with a fork for 20 seconds until the yolks and whites are completely combined with no streaks.", "Put the bread in the toaster but do not push it down yet — eggs take 4 minutes and toast takes 2.", "Put a non-stick frying pan on LOW heat and add the butter. Low is not a suggestion: high heat is what makes rubbery, watery scrambled eggs.", "When the butter has melted and stopped foaming, pour in the eggs. Start the toast now.", "Leave the eggs completely still for 20 seconds, then start stirring slowly with a spatula, scraping the bottom of the pan and folding what has set back into what has not.", "Keep stirring gently for 3 to 4 minutes. The eggs will go from liquid, to loose curds, to soft folds.", "Take the pan OFF the heat while the eggs still look slightly too wet and glossy. They carry on cooking in the hot pan for another 30 seconds and set to exactly right.", "Butter the toast, pile the eggs on and grind over a bit more pepper."]'::jsonb,'Salting the eggs before cooking is fine and seasons them evenly — the old warning about it is a myth. The real mistake is the heat being too high.'),
('garlic-butter-pasta','Garlic butter pasta','🍝','any',2,15,t,'[{"c": "pantry", "n": "Spaghetti", "q": 200, "u": "g"}, {"c": "dairy", "n": "Butter", "q": 60, "u": "g"}, {"c": "veg", "n": "Garlic", "q": 4, "u": "cloves"}, {"c": "dairy", "n": "Parmesan or mature cheddar", "q": 50, "u": "g"}, {"c": "pantry", "n": "Olive oil", "q": 1, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 1, "u": "tbsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Fill a large pot with water, add the tablespoon of salt and put it on high heat with the lid on. The lid gets it boiling several minutes faster.", "While it heats, peel the garlic and slice it as thinly as you can. Grate the cheese.", "When the water is at a full rolling boil, add the spaghetti and stir once so it does not stick. Cook for the time on the packet, usually 9 to 11 minutes.", "With 4 minutes to go, melt the butter with the olive oil in a large frying pan over LOW heat. The oil stops the butter burning.", "Add the sliced garlic and cook it gently for 3 minutes, stirring. You want it soft and barely blond. Browned garlic turns bitter and there is no fixing it — if it starts colouring, pull the pan off the heat.", "Before draining, scoop out a mug of the pasta water. This is not optional — the starch in it is what turns butter into a sauce.", "Drain the pasta and tip it straight into the garlic butter. Add 4 tablespoons of the pasta water and the black pepper.", "Toss hard over medium heat for 1 minute. The liquid goes from watery to a glossy sauce that clings to the strands. Add another splash of pasta water if it looks dry.", "Off the heat, add the cheese and toss again. Serve immediately in warm bowls."]'::jsonb,'The whole meal is store-cupboard. A tin of tuna, a handful of frozen peas or a fried egg on top all turn it into supper rather than a side.'),
('noodles-egg-veg','Noodles with egg & veg','🍜','any',2,12,t,'[{"c": "pantry", "n": "Instant noodles", "q": 2, "u": "packets"}, {"c": "dairy", "n": "Eggs", "q": 2, "u": ""}, {"c": "frozen", "n": "Frozen mixed veg", "q": 1, "u": "cup"}, {"c": "veg", "n": "Spring onion", "q": 2, "u": ""}, {"c": "pantry", "n": "Soy sauce", "q": 2, "u": "tbsp"}, {"c": "pantry", "n": "Sesame oil", "q": 1, "u": "tsp"}, {"c": "pantry", "n": "Cooking oil", "q": 1, "u": "tbsp"}]'::jsonb,'["Boil a kettle. Put the frozen veg in a pot with the noodles and pour over enough boiling water to cover.", "Simmer 3 minutes, until the noodles have loosened and the veg is hot through. Drain almost all the water off, leaving about 3 tablespoons in the pot.", "Throw away the flavour sachet, or use only half of it — you are seasoning this properly instead.", "Stir the soy sauce and sesame oil through the drained noodles. Put the lid on to keep them warm.", "Heat the cooking oil in a small frying pan over medium-high heat until it shimmers.", "Crack in the eggs and fry 2 to 3 minutes, spooning the hot oil over the whites, until the whites are set and the edges are crisp and lacy but the yolks are still soft.", "Divide the noodles between two bowls, slide a fried egg on top of each and scatter over the sliced spring onion.", "Break the yolk into the noodles as you eat — it makes the sauce."]'::jsonb,'Two-minute noodles with an egg, some veg and real soy sauce stops being a sad snack and becomes a proper bowl of food for the same 12 minutes.'),
('apple-crumble','Apple crumble','🍎','dessert',6,55,t,'[{"c": "veg", "n": "Apples", "q": 8, "u": ""}, {"c": "pantry", "n": "Brown sugar", "q": 100, "u": "g"}, {"c": "spices", "n": "Ground cinnamon", "q": 1, "u": "tsp"}, {"c": "veg", "n": "Lemon", "q": 0.5, "u": ""}, {"c": "pantry", "n": "Cake flour", "q": 180, "u": "g"}, {"c": "dairy", "n": "Butter, cold", "q": 120, "u": "g"}, {"c": "pantry", "n": "Sugar (for the crumble)", "q": 80, "u": "g"}, {"c": "pantry", "n": "Rolled oats", "q": 50, "u": "g"}, {"c": "spices", "n": "Salt", "q": 1, "u": "pinch"}]'::jsonb,'["Heat the oven to 180°C.", "Peel and core the apples and cut them into chunks about 2 cm. Smaller than that and they collapse into apple sauce.", "Toss the apple chunks in a 25 cm baking dish with the brown sugar, cinnamon and a squeeze of lemon juice. Spread them level.", "Take the butter straight from the fridge and cut it into small cubes. Cold butter is essential — soft butter makes a paste, not a crumble.", "Put the flour, salt and the cubed cold butter in a big bowl. Rub the butter into the flour with your fingertips, lifting and letting it fall, until it looks like coarse breadcrumbs with a few pea-sized lumps left. About 3 minutes.", "Stir in the 80 g sugar and the oats.", "Scatter the crumble evenly over the apples. Do not press it down — a loose topping is what goes crisp.", "Bake 35 to 40 minutes. It is ready when the top is golden brown and you can see the apple juices bubbling up thickly around the edges.", "Rest 10 minutes before serving. Custard or vanilla ice cream."]'::jsonb,'Granny Smiths hold their shape best; Golden Delicious go soft. A mix of the two is the nicest texture. Works just as well with pears or with tinned peaches.'),
('chocolate-mug-cake','Chocolate mug cake','☕','dessert',1,5,f,'[{"c": "pantry", "n": "Cake flour", "q": 4, "u": "tbsp"}, {"c": "pantry", "n": "Sugar", "q": 3, "u": "tbsp"}, {"c": "pantry", "n": "Cocoa powder", "q": 2, "u": "tbsp"}, {"c": "pantry", "n": "Baking powder", "q": 0.25, "u": "tsp"}, {"c": "spices", "n": "Salt", "q": 1, "u": "pinch"}, {"c": "dairy", "n": "Milk", "q": 3, "u": "tbsp"}, {"c": "pantry", "n": "Cooking oil", "q": 2, "u": "tbsp"}, {"c": "pantry", "n": "Vanilla essence", "q": 0.25, "u": "tsp"}, {"c": "pantry", "n": "Chocolate", "q": 2, "u": "squares"}]'::jsonb,'["Use a big mug — at least 350 ml. The cake rises to nearly double and a small mug means chocolate all over the microwave.", "Put the flour, sugar, cocoa, baking powder and salt in the mug and stir them together with a fork until you see one even colour with no cocoa streaks.", "Add the milk, oil and vanilla. Stir with the fork, getting right into the bottom corners of the mug where dry flour hides. Stop as soon as the batter is smooth.", "Push the 2 squares of chocolate into the middle of the batter until they are just covered. They melt into a molten centre.", "Microwave on full power for 70 seconds. Do not walk away — watch it rise.", "Check it: the top should look set and dry, not wet and shiny. If it is still wet, give it another 10 seconds and check again. Ten seconds too long turns it rubbery, so go in small steps.", "Let it stand 1 minute — it is dangerously hot straight out — then eat it out of the mug with a teaspoon."]'::jsonb,'Five minutes from wanting cake to eating cake. Ice cream on top while it is still warm is the whole point.'),
('dom-pedro','Dom Pedro','🥤','dessert',2,5,t,'[{"c": "frozen", "n": "Vanilla ice cream", "q": 6, "u": "scoops"}, {"c": "pantry", "n": "Whisky or Kahlua", "q": 100, "u": "ml"}, {"c": "dairy", "n": "Cream", "q": 60, "u": "ml"}, {"c": "pantry", "n": "Chocolate", "q": 1, "u": "square"}]'::jsonb,'["Take the ice cream out of the freezer 5 minutes early so it is soft enough to blend but not melted.", "Put 6 scoops of ice cream, the cream and the whisky (or Kahlua) into a blender.", "Blend in short bursts, 3 or 4 seconds at a time, until just smooth. Over-blending warms it and you end up with a thin milkshake instead of something you eat with a spoon.", "It should be thick enough that it barely moves when you tilt the jug. If it is too thin, add another scoop of ice cream and pulse once.", "Pour into two glasses.", "Grate the square of chocolate over the top and serve with both a straw and a long spoon."]'::jsonb,'Pudding and a nightcap in one glass. Kahlua for coffee-ish, whisky for the classic, Amarula for the sweetest version.'),
('malva-pudding','Malva pudding','🍮','dessert',8,65,t,'[{"c": "pantry", "n": "White sugar", "q": 200, "u": "g"}, {"c": "dairy", "n": "Eggs", "q": 2, "u": ""}, {"c": "pantry", "n": "Apricot jam", "q": 1, "u": "tbsp"}, {"c": "pantry", "n": "Cake flour", "q": 180, "u": "g"}, {"c": "pantry", "n": "Bicarbonate of soda", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Salt", "q": 1, "u": "pinch"}, {"c": "dairy", "n": "Butter", "q": 15, "u": "g"}, {"c": "pantry", "n": "White vinegar", "q": 1, "u": "tsp"}, {"c": "dairy", "n": "Milk", "q": 125, "u": "ml"}, {"c": "dairy", "n": "Cream (for the sauce)", "q": 200, "u": "ml"}, {"c": "dairy", "n": "Butter (for the sauce)", "q": 100, "u": "g"}, {"c": "pantry", "n": "Sugar (for the sauce)", "q": 150, "u": "g"}, {"c": "pantry", "n": "Hot water (for the sauce)", "q": 100, "u": "ml"}]'::jsonb,'["Heat the oven to 180°C. Grease a 20 x 25 cm ovenproof dish with butter — it must be ovenproof AND deep enough to take the sauce later.", "Beat the 200 g sugar and the 2 eggs together with an electric beater for 3 full minutes, until the mixture is pale, thick and roughly doubled in volume. This is the only lift the pudding gets, so do not cut it short.", "Beat in the apricot jam.", "In a separate bowl, stir the flour, bicarbonate of soda and salt together with a fork so the bicarb is evenly spread. Lumps of bicarb leave bitter spots.", "Melt the 15 g butter and stir it together with the vinegar and the milk in a jug. It may look slightly curdled — that is normal and correct.", "Add the flour mixture and the milk mixture to the eggs in two goes, alternating, mixing gently after each addition just until it comes together. Stop as soon as no dry flour is visible.", "Pour into the dish, level the top, and bake 40 to 45 minutes. It is done when it is deep brown on top and a skewer pushed into the middle comes out with no wet batter on it.", "About 5 minutes before it comes out, make the sauce: put the cream, 100 g butter, 150 g sugar and hot water in a small pot over medium heat.", "Stir until the butter has melted and the sugar has completely dissolved — rub a little between your fingers, it should feel smooth not gritty. Bring it just to a simmer, then take it off.", "Take the pudding out and, while it is still hot, prick it all over with a skewer — 30 or 40 holes, right down to the bottom.", "Pour ALL the hot sauce slowly over the hot pudding. It will look like far too much liquid. It is not. Both must be hot or it will not soak in.", "Leave it 20 minutes to drink the sauce up. Serve warm with cream, ice cream or custard."]'::jsonb,'Hot sauce onto hot pudding, and prick it first — those two things are the entire difference between a real malva pudding and a dry brown cake.'),
('melktert','Melktert','🥧','dessert',8,75,t,'[{"c": "frozen", "n": "Ready-made shortcrust pastry", "q": 400, "u": "g"}, {"c": "dairy", "n": "Milk", "q": 1, "u": "l"}, {"c": "spices", "n": "Cinnamon stick", "q": 1, "u": ""}, {"c": "dairy", "n": "Butter", "q": 60, "u": "g"}, {"c": "pantry", "n": "Sugar", "q": 125, "u": "ml"}, {"c": "pantry", "n": "Cake flour", "q": 60, "u": "ml"}, {"c": "pantry", "n": "Cornflour", "q": 45, "u": "ml"}, {"c": "dairy", "n": "Eggs", "q": 3, "u": ""}, {"c": "pantry", "n": "Vanilla essence", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Salt", "q": 1, "u": "pinch"}, {"c": "spices", "n": "Ground cinnamon", "q": 1, "u": "tsp"}]'::jsonb,'["Heat the oven to 200°C. Roll the pastry out and line a 24 cm pie dish with it, pressing it into the corners. Trim the edges and prick the base all over with a fork.", "Line the pastry with baking paper, fill with dried beans or rice, and bake 15 minutes. Lift the paper and beans out and bake 5 minutes more until the base is dry and pale gold. Set aside.", "Pour 800 ml of the milk into a heavy pot with the cinnamon stick and the butter. Heat over medium until it is steaming and just about to simmer, then turn it off and let the cinnamon sit in it for 5 minutes.", "Separate the 3 eggs: yolks in one bowl, whites in a clean, completely dry bowl. Any yolk in the whites and they will not whip.", "In a jug, whisk the remaining 200 ml of COLD milk with the flour, cornflour, sugar and salt until totally smooth. Cold milk here is what stops lumps forming.", "Fish the cinnamon stick out of the hot milk. Bring the milk back to a gentle simmer, then pour in the flour mixture in a steady stream, whisking hard the whole time.", "Keep whisking over medium heat for 4 to 5 minutes as it thickens into a custard. It is ready when it is thick enough to hold the mark of the whisk for a second.", "Take it off the heat. Whisk in the egg yolks one at a time, then the vanilla. Off the heat matters — direct heat now would scramble the yolks.", "Beat the egg whites to soft peaks, then fold them into the warm custard in two goes with a spatula. It should stay light and airy.", "Pour into the baked pastry case and smooth the top.", "Mix the ground cinnamon with a teaspoon of sugar and dust it generously over the surface.", "Bake 10 minutes at 200°C just to set the top. Cool to room temperature, then chill at least 2 hours before slicing — warm melktert will not cut cleanly."]'::jsonb,'Ready-made pastry is not cheating; almost nobody makes their own for this. The custard is the part that matters.'),
('pannekoek','Pannekoek with cinnamon sugar','🥞','dessert',4,40,t,'[{"c": "pantry", "n": "Cake flour", "q": 250, "u": "ml"}, {"c": "dairy", "n": "Eggs", "q": 2, "u": ""}, {"c": "dairy", "n": "Milk", "q": 500, "u": "ml"}, {"c": "pantry", "n": "Cooking oil", "q": 30, "u": "ml"}, {"c": "pantry", "n": "White vinegar", "q": 15, "u": "ml"}, {"c": "spices", "n": "Salt", "q": 1, "u": "pinch"}, {"c": "pantry", "n": "Sugar", "q": 100, "u": "g"}, {"c": "spices", "n": "Ground cinnamon", "q": 2, "u": "tsp"}, {"c": "veg", "n": "Lemon", "q": 1, "u": ""}, {"c": "dairy", "n": "Butter for the pan", "q": 30, "u": "g"}]'::jsonb,'["Put the flour and salt in a bowl and make a well in the middle. Crack in the eggs and add about a quarter of the milk.", "Whisk from the centre outwards, pulling the flour in gradually. Starting in the middle with a little liquid is how you get a smooth batter instead of a lumpy one.", "Once it is a thick smooth paste, whisk in the rest of the milk, then the oil and the vinegar. The batter should be thin — about the consistency of cream.", "Leave the batter to stand for 20 minutes. This lets the flour swell and makes the pannekoek tender rather than rubbery. Meanwhile mix the sugar and cinnamon in a small bowl.", "Heat a 22 cm non-stick pan over medium heat and wipe it with a little butter on kitchen paper.", "Pour in just enough batter to cover the base of the pan when you tilt and swirl it — a small ladleful. Swirl immediately, before it sets.", "Cook 1 to 2 minutes, until the edges lift away from the pan by themselves and the underside is patched golden. Flip with a spatula and give it 30 to 45 seconds more.", "Slide onto a plate and stack them as you go, covering the stack with a second plate so they stay warm and soft.", "The first one is always a write-off — it seasons the pan. Eat it standing up and carry on.", "To serve: sprinkle each one generously with cinnamon sugar, squeeze over some lemon juice, then roll it up tightly."]'::jsonb,'Thin, rolled and eaten hot — not fat American pancakes. The batter keeps in the fridge for 2 days and is better on day two.'),
('peppermint-crisp-tart','Peppermint Crisp tart','🍫','dessert',10,20,t,'[{"c": "pantry", "n": "Tennis biscuits", "q": 2, "u": "packets"}, {"c": "pantry", "n": "Caramel Treat", "q": 2, "u": "tins"}, {"c": "dairy", "n": "Fresh cream", "q": 500, "u": "ml"}, {"c": "pantry", "n": "Peppermint Crisp bars", "q": 3, "u": ""}]'::jsonb,'["Take the cream out of the fridge at the last possible moment — cold cream whips, room-temperature cream does not.", "Grate all 3 bars of Peppermint Crisp on the coarse side of a box grater into a bowl. Keep a small handful aside for the top.", "Whip the 500 ml of cream with an electric beater until it holds SOFT peaks — lift the beater and the peak should flop over at the tip. Stop there. Whipping to stiff peaks means the tart will not spread and can split.", "In a second large bowl, beat the 2 tins of caramel on their own for 30 seconds until smooth and loose.", "Fold the whipped cream into the caramel in three additions, using a spatula and a gentle over-and-under motion. Do not beat it — you are trying to keep the air in. Stop when it is one even colour.", "Fold in most of the grated Peppermint Crisp, keeping back the handful for the top.", "Cover the base of a 20 x 30 cm dish with a single layer of Tennis biscuits, breaking some to fill the gaps.", "Spread a third of the caramel cream over them, right to the edges.", "Repeat: biscuits, cream, biscuits, cream — finishing with a layer of cream on top. You should get three biscuit layers.", "Scatter the reserved Peppermint Crisp over the top.", "Cover and refrigerate at least 4 hours, ideally overnight. This is not optional resting time — the biscuits have to soften into cake, and a tart cut after an hour is a plate of loose biscuits."]'::jsonb,'Twenty minutes of work and then it does the rest by itself in the fridge. Make it the night before.'),
('baked-salmon','Baked salmon with potatoes & broccoli','🐟','dinner',4,45,t,'[{"c": "meat", "n": "Salmon fillets", "q": 600, "u": "g"}, {"c": "veg", "n": "Baby potatoes", "q": 600, "u": "g"}, {"c": "veg", "n": "Broccoli", "q": 1, "u": "head"}, {"c": "veg", "n": "Lemon", "q": 1, "u": ""}, {"c": "pantry", "n": "Olive oil", "q": 3, "u": "tbsp"}, {"c": "veg", "n": "Garlic", "q": 2, "u": "cloves"}, {"c": "dairy", "n": "Butter", "q": 20, "u": "g"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 200°C. Take the salmon out of the fridge so it loses its chill while the potatoes roast.", "Halve the baby potatoes and toss them on a large tray with 2 tablespoons of olive oil, the crushed garlic and 1 teaspoon of salt. Turn them all cut-side down.", "Roast 25 minutes, until the cut faces are golden and a knife goes in easily.", "Meanwhile cut the broccoli into florets and pat the salmon fillets dry with kitchen paper.", "Take the tray out. Push the potatoes to one side and lay the salmon skin-side down in the space, with the broccoli around it.", "Drizzle the last tablespoon of oil over the broccoli, season everything with the remaining salt and the pepper, and put a small piece of butter on each salmon fillet.", "Roast 12 to 15 minutes depending on thickness. Salmon is done when the flesh has turned from deep translucent orange to pale opaque pink and the flakes separate when you press gently with a fork.", "Do not push it past this point — salmon goes from perfect to dry within about 3 minutes, and white curd squeezing out of it means it has gone too far.", "Squeeze the lemon over everything and serve straight from the tray."]'::jsonb,'Omega-3 rich and gentle — great during pregnancy (cooked through, low-mercury fish). 15 min at 200°C; lemon and a little butter is all the sauce it needs.'),
('beef-stew','Beef & veg stew','🥘','dinner',6,150,t,'[{"c": "meat", "n": "Stewing beef", "q": 700, "u": "g"}, {"c": "veg", "n": "Potatoes", "q": 4, "u": ""}, {"c": "veg", "n": "Carrots", "q": 3, "u": ""}, {"c": "veg", "n": "Onion", "q": 2, "u": ""}, {"c": "veg", "n": "Celery", "q": 2, "u": "stalks"}, {"c": "pantry", "n": "Beef stock cubes", "q": 2, "u": ""}, {"c": "pantry", "n": "Tomato paste", "q": 2, "u": "tbsp"}, {"c": "pantry", "n": "Rice or samp", "q": 2, "u": "cups"}, {"c": "pantry", "n": "Cooking oil", "q": 3, "u": "tbsp"}, {"c": "pantry", "n": "Flour", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Bay leaves", "q": 2, "u": ""}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 1, "u": "tsp"}]'::jsonb,'["Cut the beef into 4 cm cubes if it is not already, and pat every piece dry with kitchen paper. Toss the cubes with the flour, 1 teaspoon of salt and the pepper until lightly coated.", "Heat the oil in a large heavy pot over high heat until it shimmers.", "Brown the beef in 3 batches, 4 to 5 minutes each, turning so at least two sides go deep brown. Lift each batch out onto a plate. Do not skip this and do not crowd the pot — the brown crust is where a stew gets its flavour, and there is no way to add it later.", "Chop the onions, carrots and celery into rough 2 cm pieces.", "Turn the heat to medium, add the vegetables to the same pot and cook 8 minutes, scraping the brown bits off the bottom as they release.", "Stir in the tomato paste and cook 1 minute.", "Return the beef and any juices. Crumble in the stock cubes, add the bay leaves and pour in 750 ml of water — enough to just cover the meat, no more.", "Bring to a bubble, then turn the heat to the lowest setting and put the lid on slightly ajar. Simmer 1 hour 30 minutes. It should barely blip; a fast boil makes beef tough and stringy.", "Peel the potatoes and cut them into 4 cm chunks. Add them to the pot and cook a further 30 minutes.", "It is done when the beef pulls apart under a fork with no resistance and the potatoes are soft. If the beef is still chewy, it needs more time, not more heat — give it another 20 minutes.", "Taste and add the rest of the salt if needed. Fish out the bay leaves.", "Cook the rice or samp and serve the stew over it."]'::jsonb,'Potjie flavours without the fire: brown the beef hard, then 2 hours low on the stove. Doubles easily and freezes in portions.'),
('beef-lasagne','Beef & vegetable lasagne','🍝','dinner',6,90,t,'[{"c": "meat", "n": "Beef mince", "q": 600, "u": "g"}, {"c": "pantry", "n": "Lasagne sheets", "q": 250, "u": "g"}, {"c": "pantry", "n": "Tinned tomatoes", "q": 2, "u": "tins"}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "veg", "n": "Carrots", "q": 2, "u": ""}, {"c": "veg", "n": "Baby marrow", "q": 2, "u": ""}, {"c": "veg", "n": "Garlic", "q": 3, "u": "cloves"}, {"c": "dairy", "n": "Milk", "q": 600, "u": "ml"}, {"c": "dairy", "n": "Butter", "q": 50, "u": "g"}, {"c": "pantry", "n": "Flour", "q": 50, "u": "g"}, {"c": "dairy", "n": "Cheddar", "q": 150, "u": "g"}, {"c": "spices", "n": "Mixed herbs", "q": 1, "u": "tbsp"}, {"c": "pantry", "n": "Tomato paste", "q": 2, "u": "tbsp"}, {"c": "pantry", "n": "Olive oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Chop the onion finely; grate the carrots and baby marrows on the coarse side of a box grater. Grating means they disappear into the sauce completely.", "Heat the olive oil in a large pan over medium heat and cook the onion, carrot and marrow for 10 minutes until soft and any water they release has cooked off.", "Add the crushed garlic and tomato paste, stir 1 minute, then turn the heat up and add the mince. Brown it for 8 minutes, leaving it still between stirs.", "Add the tinned tomatoes, mixed herbs, 1 teaspoon of salt and the pepper. Simmer uncovered on low for 25 minutes until thick. It must be thick — a loose ragu makes a lasagne that slides apart on the plate.", "Now the white sauce. Melt the butter in a pot over medium heat, add the flour and stir into a paste. Cook 2 minutes, stirring, until it smells biscuity.", "Add the milk about 100 ml at a time, whisking each lot in completely before the next. Adding it all at once is how you get lumps.", "Keep whisking 5 minutes until it thickly coats the back of a spoon. Season with the remaining salt. Take it off the heat.", "Heat the oven to 190°C. Grate the cheddar.", "Assemble in a 25 x 30 cm dish: a thin scrape of meat sauce on the base, then sheets, then a third of the meat, then a quarter of the white sauce. Repeat twice more.", "Finish with a layer of sheets, the last of the white sauce spread right to the edges, and all the cheddar. Every sheet must be covered in sauce — any dry corner stays hard.", "Bake 40 minutes, until the top is browned and bubbling and a knife pushes through the middle with no resistance.", "Rest 15 minutes before cutting. Straight out of the oven it will not hold its shape."]'::jsonb,'Grated veg hidden in the ragù. Make two — one for tonight, one for the freezer. Mild oregano and basil, no chilli.'),
('beef-potjie','Beef potjie','🔥','dinner',6,240,t,'[{"c": "meat", "n": "Beef shin or chuck, cubed", "q": 1.5, "u": "kg"}, {"c": "veg", "n": "Onions", "q": 3, "u": ""}, {"c": "veg", "n": "Garlic", "q": 4, "u": "cloves"}, {"c": "veg", "n": "Carrots", "q": 6, "u": ""}, {"c": "veg", "n": "Potatoes", "q": 8, "u": ""}, {"c": "veg", "n": "Butternut", "q": 1, "u": "small"}, {"c": "veg", "n": "Baby marrows", "q": 4, "u": ""}, {"c": "pantry", "n": "Beef stock", "q": 500, "u": "ml"}, {"c": "pantry", "n": "Red wine", "q": 250, "u": "ml"}, {"c": "pantry", "n": "Tomato paste", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Bay leaves", "q": 3, "u": ""}, {"c": "spices", "n": "Dried thyme", "q": 1, "u": "tsp"}, {"c": "pantry", "n": "Cooking oil", "q": 3, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 1, "u": "tsp"}, {"c": "other", "f": true, "n": "Charcoal or hardwood", "q": 1, "u": "bag"}]'::jsonb,'["Start the fire first, 45 minutes before you want to cook. You are cooking on COALS, never on flames. Let the wood or charcoal burn right down until the flames are gone and the coals glow grey-orange.", "Prep everything before the pot goes on, because once it starts you cannot leave it. Cut the onions into thick slices, crush the garlic, cut the carrots into thick 3 cm chunks, peel and halve the potatoes, and cut the butternut into 4 cm chunks. Cut the baby marrows into thick rounds and keep them separate — they go in last.", "Set the potjie (a number 3 or bigger) on a small bed of coals. Add the oil and let it get properly hot — a cube of beef should sizzle loudly when it touches.", "Brown the beef in 3 or 4 batches, about 4 minutes a batch, turning so it goes deep brown on at least two sides. Crowding the pot steams the meat grey instead of browning it, and the brown is where the flavour comes from. Lift each batch out onto a plate.", "Fry the onions in the same pot for 5 minutes until soft, then add the garlic and tomato paste and stir for 1 minute.", "Put the beef back in and spread it flat. Pour in the wine and the stock, add the bay leaves, thyme, salt and pepper. The liquid should come about level with the meat, no higher.", "Lid on. Rake the coals so only a thin layer sits under the pot. Now simmer for 2 hours. You want a lazy bubble — if you can clearly HEAR it boiling, drag coals away. Top up with 4 or 5 fresh coals every 30 to 40 minutes.", "After 2 hours, layer the vegetables on top of the meat without stirring: carrots first, then potatoes, then butternut. Do not push them down into the liquid. They steam rather than boil, which is the whole point of a potjie.", "Lid back on. Cook 1 hour more. Still no stirring — the first person to stir a potjie is making a stew.", "Add the baby marrows on top and cook a final 20 minutes, until a knife slides into a potato with no resistance.", "Take the lid off and check the meat falls apart under a fork. If the sauce looks thin, pull the lid off and give it 10 minutes over slightly more coals to reduce.", "Serve straight from the pot, digging down so everyone gets meat, veg and sauce. Rice or a chunk of bread on the side."]'::jsonb,'Four hours, of which three are standing next to a fire with a drink — that is the point of it. The only real rules: coals not flames, and do not stir once the veg is layered on.'),
('beef-stroganoff','Beef stroganoff with rice','🍲','dinner',4,30,t,'[{"c": "meat", "n": "Beef strips", "q": 600, "u": "g"}, {"c": "veg", "n": "Mushrooms", "q": 250, "u": "g"}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "dairy", "n": "Cream", "q": 250, "u": "ml"}, {"c": "pantry", "n": "Beef stock cubes", "q": 1, "u": ""}, {"c": "pantry", "n": "Rice", "q": 2, "u": "cups"}, {"c": "pantry", "n": "Flour", "q": 1, "u": "tbsp"}, {"c": "dairy", "n": "Butter", "q": 30, "u": "g"}, {"c": "veg", "n": "Parsley", "q": 1, "u": "handful"}, {"c": "pantry", "n": "Cooking oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Get the rice on first. Rinse 2 cups under cold water until it runs clear, then simmer in 3 and a half cups of salted water with the lid on, lowest heat, for 12 minutes. Then off the heat, lid on, 5 minutes to steam.", "Pat the beef strips completely dry with kitchen paper and season with half the salt and the pepper. Dry meat browns; wet meat steams grey.", "Slice the onion thinly and slice the mushrooms about 5 mm thick.", "Heat the oil in a large frying pan over high heat until it just starts to shimmer. Add a third of the beef in a single layer and leave it 1 minute, then turn and give it 30 seconds more. Lift it out onto a plate.", "Repeat with the other two batches. Crowding the pan drops the temperature and the meat boils in its own juice — this is why it goes in thirds.", "Turn the heat to medium, add the butter and the onion and cook 5 minutes until soft. Add the mushrooms and cook 6 minutes more, until they have released their water AND that water has boiled away and they start to brown.", "Sprinkle over the flour and stir for 1 minute so it coats everything and loses its raw smell.", "Crumble in the stock cube and add 1 cup of water a splash at a time, stirring until smooth. It will thicken quickly.", "Turn the heat to low, pour in the cream, and return the beef with any juices from the plate. Warm through for 2 minutes without letting it boil — boiling makes cream split and toughens the beef.", "Taste, add the rest of the salt if it needs it, scatter with chopped parsley and serve on the rice."]'::jsonb,'Creamy and mild — no paprika needed. Sear the strips fast, build the sauce, done in 20 minutes.'),
('bobotie','Bobotie','🍛','dinner',6,80,t,'[{"c": "meat", "n": "Beef mince", "q": 1, "u": "kg"}, {"c": "veg", "n": "Onions", "q": 2, "u": ""}, {"c": "bakery", "n": "White bread", "q": 2, "u": "slices"}, {"c": "dairy", "n": "Milk", "q": 400, "u": "ml"}, {"c": "dairy", "n": "Eggs", "q": 3, "u": ""}, {"c": "spices", "n": "Mild curry powder", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Turmeric", "q": 1, "u": "tsp"}, {"c": "pantry", "n": "Chutney", "q": 3, "u": "tbsp"}, {"c": "pantry", "n": "Sultanas", "q": 80, "u": "g"}, {"c": "pantry", "n": "Dried apricots", "q": 6, "u": ""}, {"c": "pantry", "n": "White vinegar", "q": 1, "u": "tbsp"}, {"c": "spices", "n": "Bay leaves", "q": 4, "u": ""}, {"c": "pantry", "n": "Cooking oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 180°C. Tear the 2 slices of bread into pieces, put them in a bowl and pour over 150 ml of the milk. Leave them to soak while you do everything else.", "Chop the onions finely. Chop the dried apricots into small pieces.", "Heat the oil in a large frying pan over medium heat and cook the onions for 8 minutes until soft and translucent.", "Add the curry powder and turmeric and stir for 1 minute until it smells fragrant. Frying the spice like this instead of just stirring it into the meat is what stops bobotie tasting dusty.", "Turn the heat up, add the mince and break it up with a wooden spoon. Cook for 8 minutes until no pink is left and some of it has browned.", "Squeeze the milk out of the soaked bread with your hand and add the bread to the mince (keep the squeezed-out milk in the bowl). Stir in the chutney, sultanas, apricots, vinegar and salt.", "Take it off the heat and taste it. It should be mildly sweet-savoury, not hot. Add another spoon of chutney if it needs it.", "Tip the mixture into a 25 cm ovenproof dish and press it down flat with the back of the spoon. Flat matters — a lumpy surface makes the custard pool unevenly.", "Make the custard: beat the 3 eggs with the remaining milk plus the milk squeezed from the bread, and a pinch of salt. Pour it evenly over the mince.", "Tuck the bay leaves into the custard so they stand up slightly. Bake 35 to 40 minutes.", "It is done when the top is set — give the dish a gentle shake and the custard should wobble as one piece, not slosh — and is patched golden brown.", "Rest 5 minutes before cutting. Serve with yellow rice and a spoon of chutney."]'::jsonb,'Mild by design — the curry powder here is for warmth and colour, not heat. The sultanas and apricots are not optional; the sweetness against the savoury mince is the dish.'),
('chicken-a-la-king','Chicken à la king','🍲','dinner',4,35,t,'[{"c": "meat", "n": "Chicken breasts", "q": 600, "u": "g"}, {"c": "veg", "n": "Mushrooms", "q": 250, "u": "g"}, {"c": "veg", "n": "Green pepper", "q": 1, "u": ""}, {"c": "dairy", "n": "Cream", "q": 250, "u": "ml"}, {"c": "pantry", "n": "Chicken stock cubes", "q": 1, "u": ""}, {"c": "pantry", "n": "Rice", "q": 2, "u": "cups"}, {"c": "pantry", "n": "Flour", "q": 2, "u": "tbsp"}, {"c": "dairy", "n": "Butter", "q": 40, "u": "g"}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "pantry", "n": "Cooking oil", "q": 1, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Get the rice on first: rinse 2 cups until the water runs clear, then simmer in 3 and a half cups of salted water, lid on, lowest heat, 12 minutes, then 5 minutes off the heat with the lid still on.", "Cut the chicken into 3 cm cubes. Slice the mushrooms 5 mm thick, dice the green pepper and chop the onion.", "Heat the oil in a large pan over medium-high heat. Season the chicken with half the salt and the pepper and fry it for 6 minutes, turning, until golden outside and white all through. Lift it out onto a plate.", "Turn the heat to medium, add the butter, then the onion and green pepper. Cook 5 minutes until soft.", "Add the mushrooms and cook 6 minutes more. Wait for them to release their water and for that water to boil away — mushrooms added to a sauce before this point make it grey and thin.", "Sprinkle the flour over and stir for 1 minute so it coats everything.", "Crumble in the stock cube and add 200 ml of water a splash at a time, stirring until smooth and thickened.", "Turn the heat to low, pour in the cream and return the chicken with its juices. Warm through for 3 minutes without letting it boil.", "Taste and add the rest of the salt if needed. Serve over the rice."]'::jsonb,'The sauce thickens as it stands, so add a splash of milk when reheating. Rice keeps 4 days in the fridge — cook the full 2 cups.'),
('chicken-schnitzel','Chicken schnitzel & chips','🍗','dinner',4,40,t,'[{"c": "meat", "n": "Chicken breasts", "q": 4, "u": ""}, {"c": "pantry", "n": "Cake flour", "q": 100, "u": "g"}, {"c": "dairy", "n": "Eggs", "q": 2, "u": ""}, {"c": "pantry", "n": "Breadcrumbs", "q": 150, "u": "g"}, {"c": "frozen", "n": "Frozen chips", "q": 800, "u": "g"}, {"c": "pantry", "f": true, "n": "Cooking oil", "q": 150, "u": "ml"}, {"c": "veg", "n": "Lemon", "q": 1, "u": ""}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 220°C and get the chips in first — they take longest. Spread them in a single layer on a tray, no overlapping, and bake according to the packet, usually 25 minutes.", "Lay a chicken breast flat and slice it horizontally through the middle to open it into two thin pieces. Repeat with the rest. You want 8 thin escalopes.", "Put each piece between two sheets of cling film and bash it with a rolling pin or the bottom of a pan until it is an even 1 cm thick. Even thickness is the whole game — thick spots stay raw while thin ones burn.", "Set up three plates in a row: flour seasoned with the salt and pepper, then the eggs beaten with a fork, then the breadcrumbs.", "Take each escalope through in order — flour first (shake off the excess), then egg (let the drips fall off), then press it firmly into the breadcrumbs on both sides. Use one hand for the dry plates and one for the egg or you will crumb your own fingers.", "Heat the oil in a large frying pan over medium-high heat. It is ready when a breadcrumb dropped in fizzes straight away — about 3 minutes.", "Fry two schnitzels at a time, 3 minutes a side, until deep golden. Do not crowd the pan; the oil temperature drops and they go oily instead of crisp.", "Lift them onto a plate lined with kitchen paper and sprinkle with a little salt while they are still hot.", "Serve with the chips, lemon wedges to squeeze over, and whatever sauce you like."]'::jsonb,'Crumb them in the morning and keep them on a plate in the fridge — they fry better slightly chilled, and dinner becomes a 10-minute job.'),
('cottage-pie','Cottage pie','🥧','dinner',4,60,t,'[{"c": "meat", "n": "Beef mince", "q": 500, "u": "g"}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "veg", "n": "Carrots", "q": 2, "u": ""}, {"c": "frozen", "n": "Frozen peas", "q": 1, "u": "cup"}, {"c": "pantry", "n": "Beef stock cubes", "q": 1, "u": ""}, {"c": "veg", "n": "Potatoes", "q": 6, "u": ""}, {"c": "dairy", "n": "Butter", "q": 50, "u": "g"}, {"c": "dairy", "n": "Milk", "q": 100, "u": "ml"}, {"c": "dairy", "n": "Cheddar", "q": 50, "u": "g"}, {"c": "pantry", "n": "Tomato paste", "q": 1, "u": "tbsp"}, {"c": "pantry", "n": "Cooking oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Peel the potatoes and cut them into even chunks, roughly 4 cm. Put them in a pot of cold salted water, bring to the boil and cook 20 minutes, until a knife slides in with no resistance.", "While they boil, chop the onion finely and dice the carrots small — about 1 cm, so they cook through in the time the mince takes.", "Heat the oil in a large pan over medium heat and cook the onion and carrot for 8 minutes until soft.", "Turn the heat up, add the mince and break it up. Leave it 2 minutes at a time between stirs so it browns rather than steams. About 8 minutes in total.", "Stir in the tomato paste and cook 1 minute, then crumble in the stock cube, add 200 ml of water, 1 teaspoon of salt and the pepper.", "Simmer uncovered for 15 minutes, until the liquid has reduced to a thick gravy that just coats the meat. Too wet here and the mash sinks into it. Stir the frozen peas through at the end.", "Drain the potatoes and leave them in the colander for 2 minutes to steam dry.", "Mash them with the butter and the milk, and season with the rest of the salt. Taste it — under-seasoned mash is the usual weak point of a cottage pie.", "Heat the oven to 200°C. Spoon the mince into a 25 cm dish and level it.", "Spoon the mash over in blobs and then spread it out gently to join them up. Dolloping first stops you dragging mince up into the mash.", "Rough the surface up all over with a fork — the ridges are what go crisp and brown. Scatter the grated cheddar over.", "Bake 20 to 25 minutes, until golden on top and bubbling around the edges. Rest 5 minutes before serving."]'::jsonb,'Assemble in two foil dishes: one for tonight, one for the freezer. Grate the cheddar over the mash before baking, 25 min at 200°C.'),
('chicken-broccoli-bake','Creamy chicken & broccoli bake','🥦','dinner',4,50,t,'[{"c": "meat", "n": "Chicken breasts", "q": 600, "u": "g"}, {"c": "veg", "n": "Broccoli", "q": 2, "u": "heads"}, {"c": "dairy", "n": "Cream", "q": 250, "u": "ml"}, {"c": "dairy", "n": "Cheddar", "q": 100, "u": "g"}, {"c": "pantry", "n": "Tinned mushroom soup", "q": 1, "u": "tin"}, {"c": "pantry", "n": "Rice", "q": 2, "u": "cups"}, {"c": "pantry", "n": "Cooking oil", "q": 1, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 190°C. Get the rice on: 2 cups rinsed, 3 and a half cups salted water, lid on, lowest heat, 12 minutes, then 5 minutes off the heat.", "Cut the chicken into 3 cm cubes and season with half the salt and the pepper.", "Heat the oil in a frying pan over medium-high heat and brown the chicken for 5 minutes, turning. It does not need to cook through here — it finishes in the oven.", "Cut the broccoli into small florets, no bigger than a walnut, and boil them for 3 minutes only. Drain and rinse under cold water to stop them cooking. Blanching first is what keeps them green instead of khaki.", "In a large bowl, stir the tin of mushroom soup with the cream and the remaining salt until smooth.", "Fold in the chicken and broccoli until everything is coated.", "Tip into a 25 cm baking dish and level the top. Scatter the grated cheddar over.", "Bake 25 minutes, until the top is golden and the sauce is bubbling at the edges. Check the chicken is cooked through by cutting a piece from the middle.", "Rest 5 minutes and serve over the rice."]'::jsonb,'Assembles in 10 minutes with the tinned-soup shortcut. Reheats well — a solid cook-double candidate.'),
('frikkadelle','Frikkadelle with mash & peas','🧆','dinner',4,55,t,'[{"c": "meat", "n": "Beef mince", "q": 600, "u": "g"}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "bakery", "n": "White bread", "q": 2, "u": "slices"}, {"c": "dairy", "n": "Eggs", "q": 1, "u": ""}, {"c": "veg", "n": "Potatoes", "q": 6, "u": ""}, {"c": "dairy", "n": "Milk", "q": 200, "u": "ml"}, {"c": "frozen", "n": "Frozen peas", "q": 2, "u": "cups"}, {"c": "spices", "n": "Nutmeg", "q": 1, "u": "pinch"}, {"c": "dairy", "n": "Butter", "q": 50, "u": "g"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 190°C. Tear the 2 slices of bread into a bowl and pour over 100 ml of the milk. Leave to soak 5 minutes until completely soft.", "Chop the onion as finely as you can — big pieces make the meatballs fall apart.", "Squeeze the milk out of the bread with your hands and drop the wet bread into a large bowl. The soaked bread is what keeps frikkadelle soft; mince on its own bakes hard.", "Add the mince, onion, egg, a good grating of nutmeg, 1 teaspoon of salt and the pepper.", "Mix with your hands for about a minute, until it is evenly combined and just starting to hold together. Stop there — over-working makes them dense.", "Roll into 12 balls a bit bigger than a golf ball and sit them in an oven dish with a little space between them.", "Pour half a cup of water into the dish around the meatballs (not over them) and bake 35 to 40 minutes, spooning the pan juices over them once or twice.", "They are done when browned on top and firm to a press. Cut one open to check there is no pink in the middle.", "Meanwhile peel the potatoes, cut them into even chunks, and boil in well-salted water for 20 minutes, until a knife slides in with no resistance.", "Drain the potatoes and let them steam dry in the colander for 2 minutes — wet potatoes make watery mash. Mash with the butter and the remaining 100 ml of milk, and season well.", "Boil the peas for 3 minutes and drain.", "Serve the frikkadelle on the mash with the peas and all the pan juices poured over."]'::jsonb,'Make a double batch of meatballs — they''re just as good cold in lunchboxes or in a tomato smoor later in the week.'),
('grilled-chicken-sweet-potato','Grilled chicken, sweet potato & greens','🍗','dinner',4,45,t,'[{"c": "meat", "n": "Chicken breasts", "q": 700, "u": "g"}, {"c": "veg", "n": "Sweet potatoes", "q": 4, "u": ""}, {"c": "veg", "n": "Green beans", "q": 300, "u": "g"}, {"c": "veg", "n": "Broccoli", "q": 1, "u": "head"}, {"c": "pantry", "n": "Olive oil", "q": 4, "u": "tbsp"}, {"c": "veg", "n": "Garlic", "q": 2, "u": "cloves"}, {"c": "veg", "n": "Lemon", "q": 1, "u": ""}, {"c": "spices", "n": "Paprika", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 200°C.", "Scrub the sweet potatoes and cut them into wedges about 2 cm thick at the widest point. Even wedges cook evenly — that is the whole trick with roast veg.", "Toss the wedges on a tray with 2 tablespoons of olive oil, the paprika and 1 teaspoon of salt. Spread them out so none are touching; piled-up wedges steam and go soggy.", "Roast 30 to 35 minutes, turning once halfway, until browned at the edges and soft in the middle.", "Meanwhile, slice each chicken breast horizontally into two thinner pieces so they are an even 2 cm thick.", "Rub the chicken with 1 tablespoon of oil, the crushed garlic, the remaining salt and the pepper.", "Heat a griddle or heavy frying pan over medium-high heat for 2 minutes until properly hot. Lay the chicken in and leave it alone for 5 minutes — moving it stops it browning.", "Turn and cook 4 to 5 minutes more. It is done when the thickest part is white through with no pink and the juices run clear.", "Rest the chicken on a board for 5 minutes.", "While it rests, boil the green beans and broccoli florets for 4 minutes, until just tender but still squeaky. Drain and toss with the last tablespoon of oil.", "Slice the chicken, squeeze the lemon over everything and serve."]'::jsonb,'Lean protein and slow-release carbs — a solid post-gym plate. Grill or pan the chicken, roast the sweet potato wedges. Cook double and the leftovers are tomorrow''s lunch.'),
('hake-traybake','Hake & veg traybake','🐟','dinner',4,35,t,'[{"c": "frozen", "n": "Hake fillets", "q": 600, "u": "g"}, {"c": "veg", "n": "Baby potatoes", "q": 600, "u": "g"}, {"c": "veg", "n": "Broccoli", "q": 1, "u": "head"}, {"c": "veg", "n": "Lemon", "q": 1, "u": ""}, {"c": "pantry", "n": "Olive oil", "q": 4, "u": "tbsp"}, {"c": "veg", "n": "Garlic", "q": 2, "u": "cloves"}, {"c": "dairy", "n": "Butter", "q": 30, "u": "g"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["If the hake is frozen, defrost it fully first — in the fridge overnight, or sealed in a bag under cold running water for 20 minutes. Cooking it from frozen floods the tray with water and everything boils.", "Heat the oven to 200°C.", "Halve the baby potatoes and toss them on a large oven tray with 3 tablespoons of olive oil, the crushed garlic and 1 teaspoon of salt. Spread them cut-side down in a single layer — cut-side down is how you get a browned face on each one.", "Roast 25 minutes.", "Meanwhile cut the broccoli into florets and pat the hake fillets dry with kitchen paper.", "Take the tray out and push the potatoes to the edges. Lay the hake in the middle and scatter the broccoli around it.", "Drizzle the fish and broccoli with the last tablespoon of oil, season with the remaining salt and the pepper, and dot the butter over the fish.", "Roast a further 12 to 14 minutes. The hake is done when it has turned from glassy to opaque white and flakes into chunks when you press it with a fork. Overcooked hake goes dry fast, so check at 12 minutes.", "Squeeze the lemon over the whole tray and serve straight from it."]'::jsonb,'One tray, no washing up: potatoes in first for 20 min, then fish and broccoli for 15 more. Lemon over everything at the end.'),
('sweet-sour-stirfry','Honey-soy chicken stir-fry','🥡','dinner',4,25,t,'[{"c": "meat", "n": "Chicken breasts", "q": 600, "u": "g"}, {"c": "frozen", "n": "Stir-fry veg mix", "q": 500, "u": "g"}, {"c": "pantry", "n": "Egg noodles", "q": 400, "u": "g"}, {"c": "pantry", "n": "Soy sauce", "q": 4, "u": "tbsp"}, {"c": "pantry", "n": "Honey", "q": 2, "u": "tbsp"}, {"c": "veg", "n": "Garlic", "q": 2, "u": "cloves"}, {"c": "veg", "n": "Fresh ginger", "q": 2, "u": "cm"}, {"c": "pantry", "n": "Cooking oil", "q": 2, "u": "tbsp"}, {"c": "pantry", "n": "Cornflour", "q": 1, "u": "tsp"}]'::jsonb,'["A stir-fry cooks in 6 minutes and gives you no time to chop anything once it starts. Prepare everything first and line it up next to the hob.", "Slice the chicken into thin strips across the grain, about 1 cm thick. Crush the garlic and grate the ginger.", "Mix the sauce in a cup: soy sauce, honey, garlic, ginger, the cornflour and 3 tablespoons of water. Stir until the cornflour has completely dissolved — any lumps will show up as white specks in the finished dish.", "Boil the noodles according to the packet, drain, and rinse briefly under cold water so they stop cooking and do not clump.", "Heat a wok or your largest frying pan over the highest heat for 2 minutes. It needs to be genuinely hot — this is the one dish where high heat is the point.", "Add the oil, then the chicken in a single layer. Leave it 1 minute without touching it, then stir-fry 3 minutes until no pink is left.", "Add the frozen veg straight from the freezer and stir-fry 3 minutes. It will hiss and steam; keep everything moving.", "Pour in the sauce and toss for 2 minutes. It will bubble and thicken into a glaze that clings to everything rather than pooling at the bottom.", "Add the noodles and toss for 1 minute more until heated through and coated.", "Serve immediately — a stir-fry left standing goes limp."]'::jsonb,'Fifteen-minute dinner if the chicken is sliced on prep day. Sauce = soy + honey + garlic, reduced for 2 minutes — savoury-sweet, no heat.'),
('lentil-shepherds-pie','Lentil shepherd''s pie','🥧','dinner',4,60,t,'[{"c": "pantry", "n": "Brown lentils", "q": 2, "u": "tins"}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "veg", "n": "Carrots", "q": 2, "u": ""}, {"c": "frozen", "n": "Frozen peas", "q": 1, "u": "cup"}, {"c": "pantry", "n": "Tinned tomatoes", "q": 1, "u": "tin"}, {"c": "pantry", "n": "Veg stock cubes", "q": 1, "u": ""}, {"c": "veg", "n": "Potatoes", "q": 6, "u": ""}, {"c": "dairy", "n": "Butter", "q": 40, "u": "g"}, {"c": "dairy", "n": "Milk", "q": 100, "u": "ml"}, {"c": "spices", "n": "Mixed herbs", "q": 1, "u": "tbsp"}, {"c": "pantry", "n": "Tomato paste", "q": 1, "u": "tbsp"}, {"c": "pantry", "n": "Olive oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Peel the potatoes, cut them into even 4 cm chunks and boil in well-salted water for 20 minutes, until a knife slides in with no resistance.", "Meanwhile chop the onion finely and dice the carrots to about 1 cm.", "Heat the olive oil in a large pan over medium heat and cook the onion and carrot for 10 minutes until properly soft. With no meat here, this is where all the depth comes from, so do not cut it short.", "Stir in the tomato paste and the mixed herbs and cook 1 minute.", "Drain and rinse the lentils and add them with the tinned tomatoes, the crumbled stock cube, 150 ml of water, 1 teaspoon of salt and the pepper.", "Simmer uncovered for 15 minutes until thick — it should mound on a spoon rather than run off it. Stir the peas through at the end.", "Drain the potatoes and let them steam dry in the colander for 2 minutes, then mash with the butter and milk. Season with the rest of the salt and taste it.", "Heat the oven to 200°C. Spoon the lentil mixture into a 25 cm dish and level it.", "Drop the mash on in spoonfuls and then join them up gently with the back of the spoon, so you do not drag the filling up into it.", "Rough the top all over with a fork — the peaks are what crisp.", "Bake 25 minutes until golden and bubbling at the edges. Rest 5 minutes before serving."]'::jsonb,'Meat-free, iron- and fibre-rich and easy on the stomach — good for the pregnancy weeks. Thyme and herbs, nothing hot.'),
('mac-and-cheese','Macaroni & cheese','🧀','dinner',4,45,t,'[{"c": "pantry", "n": "Macaroni", "q": 400, "u": "g"}, {"c": "dairy", "n": "Butter", "q": 60, "u": "g"}, {"c": "pantry", "n": "Cake flour", "q": 60, "u": "g"}, {"c": "dairy", "n": "Milk", "q": 750, "u": "ml"}, {"c": "dairy", "n": "Cheddar", "q": 300, "u": "g"}, {"c": "spices", "n": "Mustard powder", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Salt", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 200°C. Put a large pot of water on to boil and salt it well — it should taste like the sea.", "Grate all 300 g of cheddar now, before you start the sauce. Once the sauce is going you will not have a free hand. Keep a big handful back for the top.", "Boil the macaroni for 2 minutes LESS than the packet says. It finishes cooking in the oven, and fully cooked pasta here turns to mush. Drain it and leave it in the colander.", "In the same empty pot, melt the butter over medium heat. Add the flour and stir it into a paste. Keep stirring for 2 minutes — it should smell biscuity, not raw.", "Now add the milk about 100 ml at a time, whisking each addition until completely smooth before adding the next. Rushing this is exactly how you get a lumpy sauce.", "Once all the milk is in, keep whisking over medium heat for 5 to 6 minutes until the sauce thickens enough to coat the back of a spoon — draw a finger through it and the line should hold.", "Take it off the heat. Stir in the mustard powder, salt, pepper and all the cheese except the handful you kept back. Stir until it is completely melted and glossy.", "Tip the drained macaroni into the sauce and fold it through so every piece is coated. It will look a bit too saucy — it should, the pasta drinks it in the oven.", "Pour into a 25 cm baking dish, scatter the reserved cheese over the top and bake 20 minutes, until the top is browned in patches and the edges are bubbling.", "Let it stand 5 minutes before serving or it will run all over the plate."]'::jsonb,'Fried onion, chopped ham or a tin of tuna stirred in at step 8 all work. Assembles ahead and bakes from cold in 30 minutes.'),
('mild-chicken-curry','Mild chicken curry & rice','🍛','dinner',4,45,t,'[{"c": "meat", "n": "Chicken thighs, deboned", "q": 800, "u": "g"}, {"c": "veg", "n": "Onions", "q": 2, "u": ""}, {"c": "veg", "n": "Garlic", "q": 3, "u": "cloves"}, {"c": "veg", "n": "Fresh ginger", "q": 2, "u": "cm"}, {"c": "spices", "n": "Mild curry powder", "q": 2, "u": "tbsp"}, {"c": "pantry", "n": "Tinned tomatoes", "q": 1, "u": "tin"}, {"c": "pantry", "n": "Coconut milk", "q": 400, "u": "ml"}, {"c": "veg", "n": "Potatoes", "q": 3, "u": ""}, {"c": "pantry", "n": "Basmati rice", "q": 2, "u": "cups"}, {"c": "pantry", "n": "Cooking oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "veg", "n": "Fresh coriander", "q": 1, "u": "handful"}]'::jsonb,'["Cut the chicken thighs into 3 cm pieces. Chop the onions finely, crush the garlic, and grate the ginger on the fine side of a box grater. Peel the potatoes and cut them into 3 cm chunks.", "Heat the oil in a large deep pan over medium heat. Cook the onions for 10 minutes until soft and just golden. This is the base of the sauce — hurrying it makes a thin curry.", "Add the garlic and ginger and cook 1 minute, stirring so they do not catch.", "Add the curry powder and stir for 1 full minute until it smells warm and toasty. If the pan looks dry, add another splash of oil — the spice needs fat to release its flavour.", "Add the chicken and stir to coat every piece in the spice. Cook 5 minutes, turning, until it is white all over on the outside.", "Pour in the tinned tomatoes and the coconut milk, add the potatoes and the salt, and stir once. Bring to a gentle bubble.", "Turn the heat to low, half-cover with a lid and simmer 25 minutes. Stir every 8 minutes or so. It is done when a knife goes into a potato with no resistance and the sauce has thickened and turned a deeper orange.", "While it simmers, cook the rice: rinse 2 cups of basmati under cold water until the water runs clear, then simmer in 3 and a half cups of salted water, lid on, lowest heat, 12 minutes. Then off the heat, lid still on, 5 minutes to steam.", "Taste the curry and add salt if it needs it. Tear the coriander over the top just before serving.", "Serve over the rice, with chutney and a spoon of plain yoghurt on the side."]'::jsonb,'Mild on purpose — no chilli anywhere. If you want heat, it is better added to your own plate than to the pot.'),
('minute-steak-onions','Minute steak with fried onions','🥩','dinner',2,15,t,'[{"c": "meat", "n": "Minute steaks", "q": 4, "u": ""}, {"c": "veg", "n": "Onions", "q": 2, "u": ""}, {"c": "dairy", "n": "Butter", "q": 40, "u": "g"}, {"c": "pantry", "n": "Cooking oil", "q": 1, "u": "tbsp"}, {"c": "pantry", "n": "Worcestershire sauce", "q": 1, "u": "tbsp"}, {"c": "bakery", "n": "Bread rolls", "q": 2, "u": ""}, {"c": "spices", "n": "Salt", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Take the steaks out of the fridge and pat both sides completely dry with kitchen paper. Wet meat steams instead of browning — this one step makes the difference.", "Season both sides with the salt and pepper.", "Slice the onions into thin half-moons.", "Heat the oil and half the butter in a large frying pan over medium heat. Cook the onions for 8 minutes, stirring now and then, until soft and deep golden. Tip them onto a plate.", "Turn the heat up to high and let the pan get properly hot — 1 minute. It should be just starting to smoke.", "Lay in the steaks, not touching. Cook 1 minute a side for medium — minute steaks are thin and go from perfect to leather in about 30 seconds, so stand there and watch them.", "Take the steaks out onto a plate to rest. Turn the heat to low, add the rest of the butter and the Worcestershire sauce to the pan and stir up all the brown bits for 30 seconds.", "Put the onions back in to warm through, then spoon everything over the steaks. Serve in the rolls, or with chips."]'::jsonb,'Also works with any thin steak. The important bits are: dry the meat, get the pan properly hot, and take it off before you think you should.'),
('pap-en-wors','Pap & wors with tomato smoor','🌭','dinner',4,45,t,'[{"c": "meat", "n": "Boerewors", "q": 500, "u": "g"}, {"c": "pantry", "n": "Maize meal", "q": 2, "u": "cups"}, {"c": "veg", "n": "Tomatoes", "q": 4, "u": ""}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "pantry", "n": "Tomato paste", "q": 2, "u": "tbsp"}, {"c": "pantry", "n": "Sugar", "q": 1, "u": "tsp"}, {"c": "pantry", "n": "Cooking oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "dairy", "n": "Butter", "q": 2, "u": "tbsp"}]'::jsonb,'["Start the pap — it takes the longest. The ratio for stywe pap is 2 cups of water for every 1 cup of maize meal, so here that is 4 cups (1 litre) of water for 2 cups of meal.", "Put the water and 1 teaspoon of salt in a heavy pot with a tight lid and bring it to a hard rolling boil. Rolling boil means bubbling non-stop. Anything less and the pap goes lumpy.", "Turn the heat to low and pour the maize meal into the middle in a steady stream so it mounds up above the water. Lid on immediately and leave it completely alone for 5 minutes.", "Take the lid off and stir hard with a wooden spoon, pressing lumps against the side until smooth. Lid back on, lowest heat, 25 minutes, stirring every 8 minutes so it does not catch.", "While the pap cooks, make the smoor. Slice the onion thinly and chop the tomatoes into 2 cm chunks, keeping their juice.", "Heat the oil in a frying pan over medium heat and cook the onion for 8 minutes until soft and golden at the edges. Stir in the tomato paste and fry 1 minute.", "Add the tomatoes with their juice, the sugar and 1 teaspoon of salt. Simmer on low for 15 minutes until thick enough to sit on a spoon.", "Cook the wors: medium heat, in a large pan or on the braai. Do not prick it — every hole lets the fat out. Coil it and give it 6 minutes a side, turning once with tongs.", "Check it is cooked by cutting the thickest part: no pink, juices clear. If not, another 2 minutes a side on lower heat.", "Beat the butter into the pap. Serve a mound of pap with the wors alongside and the smoor spooned over both."]'::jsonb,'Stywe pap or krummelpap — your call. Smoor: soften onion, add chopped tomato, paste and sugar, simmer 15 min. Wors in the pan or on the braai.'),
('mp-a44e6954','Pizza','🍕','dinner',2,30,t,'[{"c": "bakery", "n": "Pizza bases", "q": 2, "u": ""}, {"c": "pantry", "n": "Tomato passata", "q": 200, "u": "ml"}, {"c": "dairy", "n": "Mozzarella", "q": 250, "u": "g"}, {"c": "pantry", "n": "Olive oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Mixed herbs", "q": 1, "u": "tsp"}, {"c": "veg", "n": "Garlic", "q": 1, "u": "clove"}, {"c": "spices", "n": "Salt", "q": 0.5, "u": "tsp"}, {"c": "other", "n": "Toppings of choice", "q": "", "u": ""}]'::jsonb,'["Turn the oven as hot as it will go — 250°C or higher — and put a baking tray or pizza stone inside to heat with it. Give it a full 20 minutes. A screaming hot surface under the base is most of what separates a good pizza from a soggy one.", "Make the sauce while it heats: stir the passata with the crushed garlic, mixed herbs, salt and 1 tablespoon of the olive oil. No cooking needed — it cooks on the pizza.", "Tear or grate the mozzarella and, if it is the wet kind in a ball, blot it on kitchen paper. Wet mozzarella floods the base.", "Prepare any toppings now and keep them sparse. Two or three things, thinly sliced. A loaded pizza steams instead of crisping.", "Spread 3 tablespoons of sauce thinly over each base, leaving a 1.5 cm border. Thin is the word — a thick layer never dries out and the middle stays soft.", "Scatter the mozzarella and toppings over, then drizzle with the last of the olive oil.", "Slide each pizza onto the preheated tray and bake 8 to 12 minutes.", "It is ready when the crust edge is puffed and blistered brown in places and the cheese is bubbling with a few golden spots. Look at the underside — it should be firm and spotted, not pale and floppy.", "Basil, rocket or fresh herbs go on AFTER it comes out of the oven. In the oven they just burn.", "Rest 2 minutes before slicing so the cheese sets enough to stay put."]'::jsonb,null),
('pork-chops-apple','Pork chops with apple & mash','🥩','dinner',4,40,t,'[{"c": "meat", "n": "Pork chops", "q": 4, "u": ""}, {"c": "veg", "n": "Apples", "q": 2, "u": ""}, {"c": "veg", "n": "Potatoes", "q": 6, "u": ""}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "dairy", "n": "Butter", "q": 60, "u": "g"}, {"c": "dairy", "n": "Milk", "q": 100, "u": "ml"}, {"c": "veg", "n": "Green beans", "q": 300, "u": "g"}, {"c": "pantry", "n": "Olive oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Take the chops out of the fridge 20 minutes before cooking and pat them completely dry with kitchen paper.", "Peel the potatoes, cut into even chunks and boil in salted water for 20 minutes until a knife slides in easily.", "While they boil, slice the onion thinly. Core the apples and cut them into thick wedges — leave the skin on, it holds them together.", "Season the chops on both sides with 1 teaspoon of salt and the pepper.", "Heat the olive oil in a large frying pan over medium-high heat until it shimmers. Lay the chops in and do not move them for 4 minutes.", "Turn and cook 4 minutes on the other side. If they have a fat rim, hold them on their edge with tongs for 1 minute to render it.", "Check with a knife into the thickest part: the juices should run clear and the meat should be just barely pale pink, not raw red. Move them to a plate to rest.", "Turn the heat to medium, add 20 g of the butter to the same pan and cook the onion for 5 minutes. Add the apple wedges and cook 6 minutes more, turning once, until soft and golden at the edges.", "Drain the potatoes, let them steam dry 2 minutes, then mash with the remaining butter, the milk and the rest of the salt.", "Boil the green beans for 4 minutes until just tender.", "Serve the chops on the mash with the apple and onion spooned over and any resting juices poured on top."]'::jsonb,'Lean pork with sweet softened apple — comforting and mild. Creamy mash and green beans round it out.'),
('roast-chicken','Roast chicken with roast veg','🍗','dinner',6,100,t,'[{"c": "meat", "n": "Whole chicken", "q": 1, "u": ""}, {"c": "veg", "n": "Potatoes", "q": 6, "u": ""}, {"c": "veg", "n": "Carrots", "q": 4, "u": ""}, {"c": "veg", "n": "Onion", "q": 2, "u": ""}, {"c": "veg", "n": "Baby marrow", "q": 3, "u": ""}, {"c": "pantry", "n": "Olive oil", "q": 4, "u": "tbsp"}, {"c": "spices", "n": "Rosemary", "q": 1, "u": "sprig"}, {"c": "veg", "n": "Garlic", "q": 1, "u": "head"}, {"c": "veg", "n": "Lemon", "q": 1, "u": ""}, {"c": "dairy", "n": "Butter", "q": 30, "u": "g"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 1, "u": "tsp"}]'::jsonb,'["Take the chicken out of the fridge 30 minutes before it goes in the oven. A fridge-cold bird cooks unevenly.", "Heat the oven to 200°C. Pat the chicken dry all over with kitchen paper, inside and out. Dry skin is crisp skin — this is the single biggest thing you can do for a roast chicken.", "Rub 2 tablespoons of olive oil all over the skin, then season generously with about half the salt and pepper, including inside the cavity.", "Cut the lemon in half and the head of garlic in half across its middle. Push both, plus the rosemary, into the cavity.", "Peel and halve the potatoes, cut the carrots into thick batons and quarter the onions. Toss them in the remaining oil and salt in a large roasting tin.", "Sit the chicken on top of the vegetables, breast up. Roast 1 hour.", "Cut the baby marrows into thick rounds. After the first hour, turn the vegetables over, add the marrows, and roast a further 20 to 25 minutes.", "Check it is done: push a skewer into the thickest part of the thigh and the juices should run completely clear with no pink. If they are pink, give it 10 minutes more and check again.", "Lift the chicken onto a board and rest it 15 minutes, loosely covered with foil. Skipping the rest is what makes dry roast chicken — this is not optional.", "While it rests, put the tin over low heat, add the butter and 100 ml of water and scrape up all the brown bits into a quick gravy.", "Carve and serve with the vegetables and the pan juices."]'::jsonb,'Cook once, eat twice: roast on Sunday and the leftover chicken carries salads, wraps and bowls all week. Herbs and garlic only — no heat.'),
('spag-bol','Spaghetti bolognese','🍝','dinner',4,45,t,'[{"c": "meat", "n": "Beef mince", "q": 500, "u": "g"}, {"c": "pantry", "n": "Spaghetti", "q": 400, "u": "g"}, {"c": "pantry", "n": "Tinned tomatoes", "q": 2, "u": "tins"}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "veg", "n": "Garlic", "q": 3, "u": "cloves"}, {"c": "veg", "n": "Carrots", "q": 1, "u": ""}, {"c": "dairy", "n": "Cheddar", "q": 60, "u": "g"}, {"c": "spices", "n": "Mixed herbs", "q": 1, "u": "tbsp"}, {"c": "pantry", "n": "Tomato paste", "q": 1, "u": "tbsp"}, {"c": "pantry", "n": "Olive oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Chop the onion finely, crush the garlic, and grate the carrot on the coarse side of a box grater. Grated rather than chopped carrot melts into the sauce and sweetens it without anyone finding lumps of carrot.", "Heat the olive oil in a large deep pan over medium heat. Add the onion and carrot with a pinch of salt and cook 8 minutes, stirring now and then, until soft and translucent. Do not let them brown.", "Add the garlic and the tomato paste and stir for 1 minute, until the paste darkens slightly.", "Turn the heat up to high and add the mince. Break it up with a wooden spoon and then LEAVE it for 2 minutes so it can catch and brown before you stir again. Repeat until most of it is browned, about 8 minutes total. Grey mince makes grey sauce.", "Add both tins of tomatoes, the mixed herbs, 1 teaspoon of salt and the pepper. Fill one empty tin a quarter with water, swill it out and add that too.", "Bring to a bubble, then turn the heat right down and simmer uncovered for at least 25 minutes, ideally 45. Stir every 10 minutes. It is ready when the oil has separated out at the edges and a spoon dragged through leaves a channel that fills in slowly.", "With 12 minutes to go, bring a large pot of water to the boil, add 1 tablespoon of salt, and cook the spaghetti for the time on the packet.", "Before draining, scoop out a mug of the pasta water — the starch in it binds the sauce to the pasta.", "Drain the spaghetti and tip it into the sauce with 3 tablespoons of the pasta water. Toss over low heat for 1 minute so every strand is coated.", "Serve with the grated cheddar over the top."]'::jsonb,'Grate the carrot into the sauce — sweetness without sugar. Sauce freezes flat in zip bags; cook pasta fresh on the night.'),
('tuna-pasta-bake','Tuna pasta bake','🐟','dinner',4,40,t,'[{"c": "pantry", "n": "Pasta", "q": 400, "u": "g"}, {"c": "pantry", "n": "Tuna", "q": 3, "u": "tins"}, {"c": "dairy", "n": "Milk", "q": 500, "u": "ml"}, {"c": "dairy", "n": "Butter", "q": 40, "u": "g"}, {"c": "pantry", "n": "Flour", "q": 40, "u": "g"}, {"c": "dairy", "n": "Cheddar", "q": 150, "u": "g"}, {"c": "frozen", "n": "Frozen peas", "q": 1, "u": "cup"}, {"c": "pantry", "n": "Sweetcorn", "q": 1, "u": "tin"}, {"c": "spices", "n": "Mustard powder", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 200°C. Put a large pot of well-salted water on to boil and grate the cheddar, keeping a handful back for the top.", "Cook the pasta for 2 minutes LESS than the packet says. It finishes in the oven, and fully cooked pasta ends up mushy. Drain it.", "Drain the tuna properly, pressing the lid down over the sink, and drain the sweetcorn.", "In the empty pot, melt the butter over medium heat. Stir in the flour to make a paste and cook 2 minutes, stirring, until it smells biscuity rather than raw.", "Add the milk 100 ml at a time, whisking each addition until completely smooth before adding the next.", "Keep whisking 5 minutes until the sauce coats the back of a spoon and holds a line when you draw a finger through it.", "Off the heat, stir in the mustard powder, salt, pepper and all the cheese except the reserved handful.", "Fold in the pasta, tuna, sweetcorn and the frozen peas straight from the freezer. Break the tuna up gently — over-stirring turns it to paste.", "Tip into a 25 cm dish, scatter the reserved cheese over and bake 20 minutes until the top is golden brown and the edges are bubbling.", "Rest 5 minutes before serving."]'::jsonb,'Storecupboard comfort with a protein hit from tinned tuna (cooked, no raw fish). Creamy cheese sauce, 20 min in the oven, reheats brilliantly.'),
('vetkoek-mince','Vetkoek with savoury mince','🥯','dinner',4,90,t,'[{"c": "pantry", "n": "Cake flour", "q": 500, "u": "g"}, {"c": "pantry", "n": "Instant yeast", "q": 10, "u": "g"}, {"c": "pantry", "n": "Sugar", "q": 2, "u": "tsp"}, {"c": "pantry", "n": "Lukewarm water", "q": 320, "u": "ml"}, {"c": "meat", "n": "Beef mince", "q": 500, "u": "g"}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "spices", "n": "Mild curry powder", "q": 1, "u": "tbsp"}, {"c": "pantry", "n": "Tinned tomatoes", "q": 1, "u": "tin"}, {"c": "pantry", "n": "Chutney", "q": 2, "u": "tbsp"}, {"c": "pantry", "f": true, "n": "Cooking oil for frying", "q": 1, "u": "l"}, {"c": "spices", "n": "Salt", "q": 2, "u": "tsp"}]'::jsonb,'["Make the dough first — it needs an hour to rise. In a big bowl, mix the flour, yeast, sugar and 1 teaspoon of the salt with a spoon until evenly combined.", "Pour in the lukewarm water — lukewarm means it feels neither warm nor cold on the inside of your wrist. Too hot kills the yeast. Mix to a rough, slightly sticky dough.", "Tip it onto a floured surface and knead for 8 minutes, pushing it away with the heel of your hand and folding it back. It goes from lumpy to smooth and springy. Poke it — the dent should slowly push back out.", "Put it back in the bowl, cover with a tea towel and leave somewhere warm for 1 hour, until doubled in size.", "While it rises, make the mince. Chop the onion and fry it in a little oil over medium heat for 8 minutes until soft. Add the curry powder, stir 1 minute, then add the mince and brown it for 8 minutes, breaking up the lumps.", "Add the tinned tomatoes, chutney and the remaining teaspoon of salt. Simmer uncovered on low for 20 minutes until thick — it should mound on a spoon, not run. Set aside.", "Punch the risen dough down and divide it into 8 pieces. Roll each into a ball and flatten it slightly into a thick disc about 8 cm across.", "Heat the oil in a deep heavy pot to 170°C — about 4 cm deep. No thermometer? Drop in a small piece of dough: it should sink, then rise and bubble steadily within 3 seconds. If it browns instantly the oil is too hot and the middles will stay raw.", "Fry 2 or 3 at a time for 4 minutes a side, turning once, until deep golden brown and hollow-sounding when tapped. Drain on kitchen paper.", "Split each hot vetkoek most of the way through and spoon the mince in. Eat with your hands, over a plate."]'::jsonb,'Deep frying: use a deep pot, never fill it more than a third with oil, and keep a lid nearby. Leftover vetkoek with butter and syrup is breakfast.'),
('quesadilla','Cheese & chicken quesadilla','🫓','lunch',2,12,t,'[{"c": "bakery", "n": "Tortilla wraps", "q": 4, "u": ""}, {"c": "dairy", "n": "Cheddar", "q": 200, "u": "g"}, {"c": "meat", "n": "Cooked chicken", "q": 200, "u": "g"}, {"c": "veg", "n": "Spring onion", "q": 2, "u": ""}, {"c": "pantry", "n": "Sweetcorn", "q": 1, "u": "tin"}, {"c": "spices", "n": "Salt", "q": 0.25, "u": "tsp"}]'::jsonb,'["Grate the cheese, shred the chicken into small pieces, slice the spring onions and drain the sweetcorn well.", "Lay a tortilla in a dry frying pan — no oil, no butter — over medium heat.", "Scatter a quarter of the cheese over the WHOLE tortilla, then the chicken, corn, spring onion and a pinch of salt over one half only.", "Cheese under everything is deliberate: it melts into the tortilla and glues the filling in so nothing falls out when you cut it.", "Cook 2 minutes, until the underside has pale brown blisters and the cheese has clearly started melting at the edges.", "Fold the empty half over with a spatula and press down. Cook 1 minute more, then flip the whole folded half-moon and give it another minute.", "Slide onto a board and let it sit for 1 minute before cutting — straight out of the pan the filling runs.", "Cut into 3 wedges. Repeat with the rest."]'::jsonb,'Nothing here is fixed except the cheese. Leftover mince, tinned beans, mushrooms, last night is all fair game.'),
('chicken-rice-bowl','Chicken & rice power bowls','🥣','lunch',4,35,t,'[{"c": "meat", "n": "Chicken breasts", "q": 600, "u": "g"}, {"c": "pantry", "n": "Rice", "q": 2, "u": "cups"}, {"c": "pantry", "n": "Sweetcorn", "q": 1, "u": "tin"}, {"c": "veg", "n": "Baby spinach", "q": 100, "u": "g"}, {"c": "veg", "n": "Carrots", "q": 2, "u": ""}, {"c": "veg", "n": "Cucumber", "q": 1, "u": ""}, {"c": "dairy", "n": "Plain yoghurt", "q": 125, "u": "ml"}, {"c": "veg", "n": "Lemon", "q": 1, "u": ""}, {"c": "pantry", "n": "Olive oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Paprika", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Rinse 2 cups of rice under cold water until the water runs clear, then simmer in 3 and a half cups of salted water with the lid on, lowest heat, 12 minutes. Off the heat, lid on, 5 minutes more.", "Slice each chicken breast horizontally into two thinner pieces so they are an even thickness and cook in the same time.", "Rub the chicken with 1 tablespoon of the olive oil, the paprika, 1 teaspoon of salt and the pepper.", "Heat a frying pan over medium-high heat for 2 minutes, then cook the chicken 5 minutes a side without moving it, until golden and white through with clear juices.", "Rest the chicken 5 minutes on a board before slicing — sliced straight away, all the juice runs out.", "Meanwhile grate the carrots, dice the cucumber and drain the sweetcorn.", "Make the dressing: stir the yoghurt with the juice of half the lemon, the last tablespoon of olive oil, the rest of the salt and a grind of pepper.", "Fluff the rice with a fork and divide it between four bowls.", "Arrange the spinach, carrot, cucumber and corn in sections on top of the rice rather than mixing them in — for lunchboxes this keeps everything from going soggy together.", "Slice the chicken and lay it over. Keep the dressing in a small separate container and pour it on just before eating."]'::jsonb,'Balanced macros in one bowl — protein, carbs and veg. Batch the chicken and rice on Sunday, assemble each morning. A yoghurt-lemon drizzle instead of anything hot.'),
('chicken-mayo-pasta','Chicken mayo pasta salad','🥗','lunch',4,30,t,'[{"c": "pantry", "n": "Pasta shells", "q": 300, "u": "g"}, {"c": "meat", "n": "Chicken breasts", "q": 400, "u": "g"}, {"c": "pantry", "n": "Mayonnaise", "q": 5, "u": "tbsp"}, {"c": "pantry", "n": "Sweetcorn", "q": 1, "u": "tin"}, {"c": "veg", "n": "Spring onion", "q": 3, "u": ""}, {"c": "veg", "n": "Peppers", "q": 1, "u": ""}, {"c": "veg", "n": "Lemon", "q": 0.5, "u": ""}, {"c": "pantry", "n": "Olive oil", "q": 1, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Boil the pasta shells in well-salted water for the time on the packet. Drain and rinse under cold water until they are completely cool. Rinsing washes off the surface starch, which is what stops a pasta salad turning into a solid lump in the fridge.", "Meanwhile season the chicken with half the salt and the pepper and fry in the olive oil over medium-high heat, 6 minutes a side, until white through with clear juices. Rest 5 minutes, then dice into 2 cm pieces.", "Drain the sweetcorn well. Dice the pepper small and slice the spring onions, greens included.", "Put the cooled pasta, chicken, corn, pepper and spring onion in a large bowl.", "Add the mayonnaise, the juice of half a lemon, the remaining salt and a grind of pepper, and fold everything together until evenly coated.", "Taste and adjust. It should be lightly dressed, not heavy — remember pasta absorbs mayo overnight and what looks right now will look dry tomorrow.", "Keep 2 tablespoons of mayonnaise back in the fridge and stir a little through each portion before eating to freshen it up.", "Chill at least 30 minutes before serving. Keeps 3 days covered."]'::jsonb,'Classic work-lunch prep: keeps 3 days in the fridge. Dress lightly on prep day and keep a little mayo back to refresh it.'),
('chicken-mayo-toastie','Chicken mayo toastie','🥪','lunch',2,12,t,'[{"c": "meat", "n": "Cooked chicken", "q": 200, "u": "g"}, {"c": "pantry", "n": "Mayonnaise", "q": 3, "u": "tbsp"}, {"c": "bakery", "n": "Bread", "q": 4, "u": "slices"}, {"c": "dairy", "n": "Cheddar", "q": 80, "u": "g"}, {"c": "veg", "n": "Spring onion", "q": 1, "u": ""}, {"c": "dairy", "n": "Butter", "q": 30, "u": "g"}, {"c": "spices", "n": "Salt", "q": 1, "u": "pinch"}, {"c": "spices", "n": "Black pepper", "q": 0.25, "u": "tsp"}]'::jsonb,'["Shred the cooked chicken with two forks, or just tear it with your fingers, into pieces about the size of your thumbnail.", "Slice the spring onion thinly, green parts and all.", "Mix the chicken, mayonnaise, spring onion, salt and pepper in a bowl. It should be just held together, not swimming — add a little more mayo only if it looks dry.", "Grate the cheddar.", "Butter one side of each bread slice. Butter goes on the outside, against the pan.", "Build two sandwiches butter-side-out: chicken mayo on the bottom slice, cheese on top of it, then the second slice.", "Put a frying pan on medium heat and cook the sandwiches 3 minutes a side, pressing down with a spatula, until golden brown and the cheese has melted.", "Cut in half and eat hot."]'::jsonb,'Built for leftover roast chicken. A supermarket rotisserie chicken gives you three of these plus tomorrow lunch.'),
('couscous-salad','Couscous & roast veg salad','🥙','lunch',4,40,t,'[{"c": "pantry", "n": "Couscous", "q": 2, "u": "cups"}, {"c": "veg", "n": "Peppers", "q": 2, "u": ""}, {"c": "veg", "n": "Courgettes", "q": 2, "u": ""}, {"c": "veg", "n": "Red onion", "q": 1, "u": ""}, {"c": "dairy", "n": "Feta", "q": 1, "u": "round"}, {"c": "pantry", "n": "Olive oil", "q": 5, "u": "tbsp"}, {"c": "veg", "n": "Lemon", "q": 1, "u": ""}, {"c": "pantry", "n": "Veg stock cubes", "q": 1, "u": ""}, {"c": "veg", "n": "Fresh mint", "q": 1, "u": "handful"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 200°C.", "Cut the peppers, courgettes and red onion into rough 3 cm pieces. Keep them big — small pieces of veg burn before they soften.", "Toss them on a large tray with 3 tablespoons of the olive oil, 1 teaspoon of salt and the pepper. Spread them in one layer with space between; a crowded tray steams instead of roasting.", "Roast 25 to 30 minutes, turning once, until the edges are browned and slightly charred. That char is most of the flavour in this salad.", "While the veg roasts, boil a kettle and dissolve the stock cube in 2 and a half cups of boiling water.", "Put the couscous in a bowl and pour the hot stock over it — the liquid should sit about 1 cm above the grains. Cover the bowl tightly with a plate or cling film.", "Leave it 8 minutes. Do not stir it, do not lift the plate. It cooks purely on trapped steam.", "Uncover and fluff it thoroughly with a fork, dragging through to separate every grain. Add 1 tablespoon of olive oil while it is still warm so it does not clump.", "Tip the roasted veg into the couscous with all the oil and juices from the tray and fold it through.", "Dress with the juice of the whole lemon and the last tablespoon of oil. Taste and add the rest of the salt.", "Crumble the feta over and tear the mint on top. Serve warm or at room temperature."]'::jsonb,'Roast a big tray of veg once; it carries this salad plus sides for two dinners. Couscous takes 5 minutes — boiling water, cover, done.'),
('chicken-salad-bowl','Grilled chicken salad bowl','🥗','lunch',4,25,t,'[{"c": "meat", "n": "Chicken breasts", "q": 500, "u": "g"}, {"c": "veg", "n": "Mixed lettuce", "q": 1, "u": "bag"}, {"c": "veg", "n": "Cucumber", "q": 1, "u": ""}, {"c": "veg", "n": "Cherry tomatoes", "q": 250, "u": "g"}, {"c": "veg", "n": "Avocado", "q": 2, "u": ""}, {"c": "dairy", "n": "Feta", "q": 1, "u": "round"}, {"c": "pantry", "n": "Olive oil", "q": 4, "u": "tbsp"}, {"c": "veg", "n": "Lemon", "q": 1, "u": ""}, {"c": "spices", "n": "Salt", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Take the chicken out of the fridge 10 minutes early — fridge-cold chicken cooks unevenly. Pat both sides dry with kitchen paper.", "If the breasts are thicker than about 2 cm at one end, slice them horizontally into two thinner pieces. Even thickness is what stops the thin end drying out while the thick end is still raw.", "Season both sides with half the salt and the pepper, and rub with 1 tablespoon of the olive oil.", "Heat a griddle or frying pan over medium-high heat until it is properly hot — 2 minutes. Lay the chicken in and do not move it.", "Cook 5 to 6 minutes a side. It is done when the thickest part is white all the way through with no pink and the juices run clear. Cut into one to check; guessing costs you nothing but dry chicken.", "Move the chicken to a board and leave it to rest 5 minutes before slicing. Resting keeps the juices in the meat instead of on the board.", "While it rests, wash and dry the lettuce, halve the cherry tomatoes, dice the cucumber and slice the avocados.", "Make the dressing: whisk the remaining 3 tablespoons of olive oil with the juice of the whole lemon, the rest of the salt and a grind of pepper until it looks thickened and combined.", "Slice the chicken across the grain into finger-thick strips.", "Pile the salad into bowls, lay the chicken over, crumble the feta on top, and pour the dressing over only at the moment you sit down — dressed leaves wilt within minutes."]'::jsonb,'High protein, low fuss. Grill the chicken on prep day and keep the dressing separate so it stays crisp across three days of lunches.'),
('toasted-cheese-tomato','Toasted cheese & tomato sarmie','🥪','lunch',2,10,t,'[{"c": "bakery", "n": "Bread", "q": 4, "u": "slices"}, {"c": "dairy", "n": "Cheddar", "q": 120, "u": "g"}, {"c": "veg", "n": "Tomato", "q": 1, "u": ""}, {"c": "dairy", "n": "Butter", "q": 30, "u": "g"}, {"c": "pantry", "n": "Chutney", "q": 2, "u": "tsp"}, {"c": "spices", "n": "Salt", "q": 1, "u": "pinch"}]'::jsonb,'["Grate the cheddar — do not slice it. Grated cheese melts in half the time and reaches the corners.", "Slice the tomato thinly, about 3 mm, and lay the slices on kitchen paper for a minute. Wet tomato is what makes a soggy toastie.", "Butter one side of each slice of bread, all the way to the edges. The buttered sides go on the OUTSIDE, against the pan.", "Build two sandwiches butter-side-out: chutney on the inside of the bottom slice, then tomato, a pinch of salt, then the grated cheese, then the top slice.", "Put a frying pan on medium heat — not high. High heat browns the bread before the cheese has any chance to melt.", "Lay the sandwiches in the dry pan (the butter is already on the bread) and press down with a spatula or a second pan.", "Cook 3 minutes, until the underside is golden brown. Lift a corner with the spatula to check rather than guessing.", "Flip and cook 3 minutes more, pressing again. It is done when both sides are golden and cheese is oozing at the edges.", "Cut in half diagonally and eat straight away — a toastie waits for nobody."]'::jsonb,'A sandwich press does this in 4 minutes with no flipping. Same build, same butter-side-out rule.'),
('tuna-wraps','Tuna & sweetcorn wraps','🌯','lunch',4,10,t,'[{"c": "bakery", "n": "Tortilla wraps", "q": 8, "u": ""}, {"c": "pantry", "n": "Tuna", "q": 3, "u": "tins"}, {"c": "pantry", "n": "Sweetcorn", "q": 1, "u": "tin"}, {"c": "pantry", "n": "Mayonnaise", "q": 3, "u": "tbsp"}, {"c": "veg", "n": "Lettuce", "q": 1, "u": "head"}, {"c": "veg", "n": "Cucumber", "q": 1, "u": ""}, {"c": "veg", "n": "Lemon", "q": 0.5, "u": ""}, {"c": "spices", "n": "Salt", "q": 0.5, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.25, "u": "tsp"}]'::jsonb,'["Open the tins of tuna and press the lid down hard over the sink to squeeze out as much liquid as you can. Wet tuna makes a wrap that falls apart.", "Drain the sweetcorn in a sieve and shake it dry.", "Tip the tuna into a bowl and flake it apart with a fork. Add the sweetcorn, mayonnaise, a squeeze of lemon, the salt and the pepper, and mix.", "Taste it. It should be just bound together, not swimming in mayo. Add a little more only if it looks dry.", "Shred the lettuce into ribbons and slice the cucumber thinly.", "Lay a wrap flat and spoon an eighth of the mix in a line down the middle, leaving 4 cm clear at each end. Overfilling is the main reason wraps burst.", "Add lettuce and cucumber on top of the tuna, not underneath — the tuna against the tortilla keeps the salad crisp.", "Fold the two short ends in first, then roll the whole thing up tightly from one long side.", "Cut in half on the diagonal. For a lunchbox, roll it in foil first and cut through the foil."]'::jsonb,'Mix the tuna filling on prep day; build wraps fresh each morning so they don''t go soggy.'),
('braaibroodjies','Braaibroodjies','🥪','side',4,20,t,'[{"c": "bakery", "n": "White bread", "q": 8, "u": "slices"}, {"c": "dairy", "n": "Butter", "q": 80, "u": "g"}, {"c": "dairy", "n": "Cheddar", "q": 200, "u": "g"}, {"c": "veg", "n": "Tomatoes", "q": 2, "u": ""}, {"c": "veg", "n": "Onion", "q": 1, "u": ""}, {"c": "pantry", "n": "Chutney", "q": 4, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 0.5, "u": "tsp"}]'::jsonb,'["Butter all 8 slices of bread on ONE side, right to the edges. The buttered sides face outwards, against the grid — that is what makes them crisp.", "Turn 4 slices butter-side-down on a board. These are your bottoms.", "Spread a tablespoon of chutney on the dry side of each bottom slice.", "Slice the tomatoes thinly and the onion very thinly. Grate the cheddar.", "Build each one: tomato slices, a scatter of raw onion, a pinch of salt, then a generous handful of grated cheese. Cheese last so it glues the top on.", "Close with the remaining slices, butter-side UP. Press down gently.", "Clamp them in a hinged braai grid. This matters — without the grid you cannot turn them without losing the filling.", "Braai high above the coals, well away from the hot part of the fire. They burn in seconds if the coals are fierce. Give them 3 to 4 minutes a side, turning often, until golden brown and the cheese has melted.", "Cut each in half diagonally and eat immediately, while the cheese still pulls."]'::jsonb,'Braai them near the end, once the coals have died down and the meat is resting. Mrs Balls is the traditional chutney.'),
('krummelpap','Krummelpap (crumbly braai pap)','🌾','side',6,45,t,'[{"c": "pantry", "n": "Maize meal (braaipap or special)", "q": 4, "u": "cups"}, {"c": "pantry", "n": "Water", "q": 750, "u": "ml"}, {"c": "spices", "n": "Salt", "q": 1.5, "u": "tsp"}, {"c": "dairy", "n": "Butter", "q": 3, "u": "tbsp"}]'::jsonb,'["Krummelpap is the odd one out: MORE maize meal than water. Use 2 cups of maize meal for every 1 and a half cups of water. Here that is 4 cups meal to 3 cups (750 ml) water.", "Bring the 3 cups of water and 1 and a half teaspoons of salt to a rolling boil in a large heavy pot with a tight lid.", "Take the pot off the heat for a second and tip all 4 cups of maize meal into the middle, letting it pile up into a pyramid standing above the water. Do not stir — stirring now gives you a solid lump instead of crumbs.", "Lid on, back on the lowest heat, and leave it alone for 12 minutes.", "Now take a big fork (a braai fork or a dinner fork, not a spoon) and drag it through the pap, breaking the mound apart into loose crumbs. Keep going until the whole pot looks like coarse breadcrumbs with no wet patches.", "Dot the butter over, put the lid back on and steam on the lowest heat for another 20 minutes. Fluff it with the fork once halfway.", "It is done when the crumbs are dry, separate and taste cooked rather than raw. If it is still a bit raw, sprinkle over 2 tablespoons of hot water, fork it through and steam 10 minutes more.", "Serve in a big bowl next to the braai, with tomato-and-onion smoor or chakalaka spooned over each helping."]'::jsonb,'Braai pap. It only works with a tight-fitting lid — the whole thing cooks on trapped steam, so every peek costs you time.'),
('mieliepap-guide','Mieliepap — which pap do I want?','🌽','side',4,null,f,'[{"c": "pantry", "n": "Maize meal (super or special)", "q": 1, "u": "kg bag"}, {"c": "spices", "n": "Salt", "q": 1, "u": "tsp"}]'::jsonb,'["All four paps are the same two ingredients — maize meal, water and salt. The ONLY thing that changes is how much water. More water, softer pap. That is the whole secret.", "SLAP PAP (soft breakfast porridge, eat it with a spoon): 1 cup maize meal to 5 cups water.", "SOETPAP (slap pap made sweet, for breakfast): same 1 to 5, then sugar, butter and milk stirred in at the end.", "STYWE PAP (stiff, holds its shape, the one you eat with wors): 1 cup maize meal to 2 cups water.", "KRUMMELPAP (dry and crumbly, the braai one): 2 cups maize meal to 1 and a half cups water. Note this one is the other way round — more meal than water.", "The one rule that matters: the water must be at a proper rolling boil, bubbling hard, before the maize meal goes anywhere near it. Lukewarm water is what makes lumps.", "The second rule: once the meal is in, put the lid on and LEAVE IT for 5 minutes. Do not stir. Stirring too early is the other thing that makes lumps.", "Got lumps anyway? Take it off the heat and beat it hard with a wooden spoon or a whisk for a minute. Most lumps break up. Truly stubborn ones — push the pap through a sieve.", "Salt goes in the water at the start, about 1 teaspoon per litre. Salting at the end never tastes the same."]'::jsonb,'Start here if you are not sure which one you want. Super maize meal is the fine one and is the most forgiving; special maize meal is coarser and takes a bit longer.'),
('slap-pap','Slap pap (soft breakfast porridge)','🥣','side',4,35,t,'[{"c": "pantry", "n": "Maize meal (super)", "q": 1, "u": "cup"}, {"c": "pantry", "n": "Water", "q": 1.25, "u": "l"}, {"c": "spices", "n": "Salt", "q": 1, "u": "tsp"}, {"c": "dairy", "n": "Butter", "q": 1, "u": "tbsp"}]'::jsonb,'["Measure 5 cups (1.25 litres) of water into a medium pot — one with a lid. Add 1 teaspoon of salt.", "Put it on high heat and bring it to a rolling boil. Rolling boil means big bubbles breaking the surface non-stop, not a few lazy ones. This takes about 6 minutes.", "While you wait: measure 1 cup of maize meal into a jug and stir in half a cup of COLD water until it looks like thin cream with no dry bits. This slurry is the trick that keeps slap pap smooth.", "Turn the heat down to medium. Pour the slurry into the boiling water in a slow stream while stirring with a whisk the whole time.", "Keep whisking for 1 minute — it will thicken quite fast. Then put the lid on, turn the heat to the lowest setting your hob has.", "Cook 25 minutes, stirring for a few seconds every 5 minutes so nothing catches on the bottom. If it gets thicker than you like, stir in a splash of boiling water.", "It is done when it tastes soft and creamy with no raw-flour graininess. Stir in the butter off the heat.", "Serve straight away in bowls, with cold milk poured over and sugar to taste."]'::jsonb,'Breakfast pap. It thickens a lot as it stands, so make it slightly runnier than you want it. Leftovers set solid in the fridge — slice and fry in butter the next morning.'),
('soetpap','Soetpap (sweet porridge)','🍯','side',4,35,t,'[{"c": "pantry", "n": "Maize meal (super)", "q": 1, "u": "cup"}, {"c": "pantry", "n": "Water", "q": 1.25, "u": "l"}, {"c": "spices", "n": "Salt", "q": 1, "u": "tsp"}, {"c": "dairy", "n": "Butter", "q": 2, "u": "tbsp"}, {"c": "pantry", "n": "Brown sugar", "q": 4, "u": "tbsp"}, {"c": "dairy", "n": "Milk", "q": 250, "u": "ml"}, {"c": "spices", "n": "Cinnamon", "q": 0.5, "u": "tsp"}]'::jsonb,'["Soetpap is slap pap with sugar and butter beaten in at the end. Make the slap pap first, exactly as below.", "Bring 5 cups (1.25 litres) of water and 1 teaspoon of salt to a hard rolling boil in a medium pot with a lid.", "While it heats, stir 1 cup of maize meal into half a cup of cold water in a jug until smooth — no dry lumps.", "Turn the heat to medium and pour the slurry in slowly, whisking non-stop. Whisk for a minute as it thickens.", "Lid on, lowest heat, 25 minutes. Give it a stir every 5 minutes.", "Take the pot off the heat. Beat in the butter first, then the brown sugar and the cinnamon. Taste and add more sugar if you want — it should be properly sweet, not just faintly.", "Spoon into bowls and pour cold milk around the edge so it pools. Do not stir the milk in — half the point is the cold milk against the hot pap."]'::jsonb,'Breakfast, or pudding if you are honest about it. A spoon of golden syrup instead of the brown sugar is the other way people make it.'),
('stywe-pap','Stywe pap (stiff pap for braai)','🌽','side',4,40,t,'[{"c": "pantry", "n": "Maize meal (super or special)", "q": 2, "u": "cups"}, {"c": "pantry", "n": "Water", "q": 1, "u": "l"}, {"c": "spices", "n": "Salt", "q": 1, "u": "tsp"}, {"c": "dairy", "n": "Butter", "q": 2, "u": "tbsp"}]'::jsonb,'["Put 4 cups (1 litre) of water and 1 teaspoon of salt in a heavy pot with a tight lid. The ratio is 2 cups of water for every 1 cup of maize meal.", "Bring it to a hard rolling boil on high heat — bubbling non-stop, about 5 minutes. This has to be a real boil or the pap goes lumpy.", "Turn the heat down to low. Pour the 2 cups of maize meal into the middle of the pot in a steady stream so it mounds up into a little island above the water. Do NOT stir it.", "Put the lid on and leave it completely alone for 5 minutes. Set a timer and walk away — this is the step people ruin.", "Take the lid off and stir hard with a wooden spoon, pressing any lumps against the side of the pot until it is smooth and thick.", "Lid back on, lowest heat, 25 minutes. Stir every 8 minutes or so, scraping the bottom, so it does not catch and burn.", "It is ready when it holds its shape on the spoon and tastes cooked through, not chalky. Beat in the butter.", "Turn it out onto a plate in one lump, or spoon it out in wedges. Serve with wors and tomato smoor over the top."]'::jsonb,'The pap for braaivleis. If it goes stiffer than you want, beat in boiling water a tablespoon at a time — never cold water, that makes it gluey.'),
('tamatie-smoor','Tamatiesmoor (tomato & onion sauce)','🍅','side',4,25,t,'[{"c": "veg", "n": "Onions", "q": 2, "u": ""}, {"c": "veg", "n": "Ripe tomatoes", "q": 6, "u": ""}, {"c": "pantry", "n": "Tomato paste", "q": 1, "u": "tbsp"}, {"c": "pantry", "n": "Sugar", "q": 1, "u": "tsp"}, {"c": "pantry", "n": "Cooking oil", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Black pepper", "q": 0.5, "u": "tsp"}]'::jsonb,'["Peel the onions and cut them in half through the root, then slice each half into thin half-moons.", "Cut the tomatoes into rough 2 cm chunks. Keep every drop of juice from the board — that is the sauce.", "Heat the oil in a frying pan over medium heat. Add the onions and a pinch of the salt.", "Cook the onions for 8 to 10 minutes, stirring now and then, until they are soft and see-through and just starting to go golden at the edges. Do not rush this on high heat — hard-fried onion tastes sharp.", "Stir in the tomato paste and let it fry for 1 minute — it darkens slightly and stops smelling tinny.", "Add the tomatoes and their juice, the sugar, the rest of the salt and the pepper. Stir once.", "Turn the heat to low and simmer uncovered for 12 to 15 minutes, stirring occasionally, until the tomatoes have collapsed and the sauce is thick enough to sit in a spoon rather than run off it.", "Taste. It should be a little sweet and a little sharp. Add a pinch more sugar if the tomatoes were sour."]'::jsonb,'This is what goes over pap. Also good on toast with a fried egg, or stirred through mince. Doubles easily and keeps 4 days in the fridge.'),
('nachos','Cheesy nachos','🧀','snack',4,15,t,'[{"c": "pantry", "n": "Corn chips", "q": 250, "u": "g"}, {"c": "dairy", "n": "Cheddar", "q": 250, "u": "g"}, {"c": "veg", "n": "Tomatoes", "q": 2, "u": ""}, {"c": "veg", "n": "Spring onions", "q": 3, "u": ""}, {"c": "dairy", "n": "Sour cream", "q": 150, "u": "ml"}, {"c": "veg", "n": "Avocado", "q": 1, "u": ""}, {"c": "pantry", "n": "Tinned black beans", "q": 1, "u": "tin"}, {"c": "spices", "n": "Salt", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 200°C. Grate the cheese, dice the tomatoes, slice the spring onions and drain and rinse the beans.", "Spread half the corn chips over a large oven tray in a single layer. A pile 5 cm deep gives you burnt chips on top and cold ones underneath.", "Scatter half the beans and half the cheese over that layer.", "Add the rest of the chips, then the rest of the beans and cheese. Two thin layers means every chip gets cheese, which is the entire art of nachos.", "Bake 8 minutes, until the cheese has completely melted and is bubbling. Watch from 6 minutes — the edges catch fast.", "While it bakes, mash the avocado with a pinch of salt.", "Take the tray out and scatter the tomato and spring onion over the hot nachos.", "Dot with spoonfuls of the sour cream and the mashed avocado and serve straight off the tray while everything is still molten."]'::jsonb,'Leftover mince or shredded chicken between the layers turns this into supper. Add fresh things after baking, never before.'),
('garlic-bread','Garlic bread','🥖','snack',4,15,t,'[{"c": "bakery", "n": "French loaf", "q": 1, "u": ""}, {"c": "dairy", "n": "Butter, soft", "q": 120, "u": "g"}, {"c": "veg", "n": "Garlic", "q": 4, "u": "cloves"}, {"c": "veg", "n": "Fresh parsley", "q": 1, "u": "handful"}, {"c": "spices", "n": "Salt", "q": 0.5, "u": "tsp"}]'::jsonb,'["Heat the oven to 200°C. Take the butter out now — it must be properly soft to spread, and 10 minutes on the counter usually does it. In a hurry, microwave it 8 seconds at a time.", "Crush the garlic cloves. Chop the parsley finely.", "Mash the soft butter, garlic, parsley and salt together with a fork until it is one even green-flecked paste.", "Cut the loaf into 2 cm slices but stop about 1 cm from the bottom so the loaf stays joined along its base. Putting a wooden spoon alongside the loaf stops the knife going all the way through.", "Push butter into every single cut with a table knife, then smear whatever is left over the top.", "Wrap the whole loaf in foil and bake 10 minutes.", "Open the foil up, folding it down around the sides, and bake 4 minutes more so the top crisps and browns.", "Pull the slices apart and serve immediately — garlic bread goes leathery within 10 minutes of coming out."]'::jsonb,'Make the butter in bulk and keep it rolled in cling film in the fridge; it also melts onto steak, corn or vegetables.'),
('hummus-veg-sticks','Hummus & veg sticks','🥕','snack',4,10,t,'[{"c": "pantry", "n": "Tinned chickpeas", "q": 1, "u": "tin"}, {"c": "pantry", "n": "Tahini", "q": 2, "u": "tbsp"}, {"c": "veg", "n": "Lemon", "q": 1, "u": ""}, {"c": "veg", "n": "Garlic", "q": 1, "u": "clove"}, {"c": "pantry", "n": "Olive oil", "q": 3, "u": "tbsp"}, {"c": "veg", "n": "Carrots", "q": 3, "u": ""}, {"c": "veg", "n": "Cucumber", "q": 1, "u": ""}, {"c": "spices", "n": "Salt", "q": 0.75, "u": "tsp"}]'::jsonb,'["Drain the chickpeas but KEEP the liquid from the tin in a cup. You will need it, and water is not as good a substitute.", "Rinse the chickpeas under the tap for 20 seconds to wash off the tinny taste.", "Put the chickpeas, tahini, the juice of the whole lemon, the peeled garlic clove, the olive oil and the salt in a food processor.", "Blend for 2 minutes. It will look thick and grainy at first — keep going.", "With the motor running, add the reserved chickpea liquid a tablespoon at a time until it turns pale, smooth and creamy. Usually 4 to 5 tablespoons. Adding liquid slowly is what makes it fluffy rather than sloppy.", "Taste it. Hummus almost always needs more lemon and more salt than you expect. Adjust and blend once more.", "Peel the carrots and cut them and the cucumber into sticks about the length of your finger.", "Spread the hummus in a shallow bowl, make a swirl in it with the back of a spoon, and pour a little olive oil into the swirl."]'::jsonb,'Keeps 4 days covered in the fridge. Also the best sandwich spread in the house.'),
('peanut-butter-oat-balls','Peanut butter oat balls','🥜','snack',12,15,t,'[{"c": "pantry", "n": "Rolled oats", "q": 200, "u": "g"}, {"c": "pantry", "n": "Peanut butter", "q": 150, "u": "g"}, {"c": "pantry", "n": "Honey", "q": 80, "u": "ml"}, {"c": "pantry", "n": "Desiccated coconut", "q": 40, "u": "g"}, {"c": "pantry", "n": "Dark chocolate chips", "q": 60, "u": "g"}, {"c": "pantry", "n": "Vanilla essence", "q": 1, "u": "tsp"}, {"c": "spices", "n": "Salt", "q": 1, "u": "pinch"}]'::jsonb,'["No cooking at all in this one. Put the oats, coconut, chocolate chips and salt in a large bowl and stir them together.", "Warm the peanut butter and honey together in the microwave for 20 seconds. Warming makes them pourable, which is the difference between mixing this in one minute and fighting it for five.", "Stir the vanilla into the warm peanut butter and honey, then pour the lot over the oats.", "Mix with a spoon, then finish with your hands, squeezing until there are no dry oats left. It should hold together when you press a bit in your fist. If it crumbles, add another tablespoon of honey.", "Put the bowl in the fridge for 10 minutes. Cold mixture rolls cleanly; warm mixture sticks to your hands.", "Roll into 12 balls, each about the size of a walnut. Wet your hands slightly if it starts sticking.", "Keep them in a sealed container in the fridge. They firm up properly after an hour and keep for 2 weeks."]'::jsonb,'Roughly 150 calories each with a decent protein hit — the useful thing to have in the fridge when you get home from gym hungry.'),
('plaatkoekies','Plaatkoekies (crumpets)','🥞','snack',4,25,t,'[{"c": "pantry", "n": "Cake flour", "q": 250, "u": "ml"}, {"c": "pantry", "n": "Baking powder", "q": 2, "u": "tsp"}, {"c": "pantry", "n": "Sugar", "q": 2, "u": "tbsp"}, {"c": "spices", "n": "Salt", "q": 1, "u": "pinch"}, {"c": "dairy", "n": "Egg", "q": 1, "u": ""}, {"c": "dairy", "n": "Milk", "q": 200, "u": "ml"}, {"c": "dairy", "n": "Butter, melted", "q": 30, "u": "g"}, {"c": "dairy", "n": "Butter for serving", "q": 50, "u": "g"}, {"c": "pantry", "n": "Golden syrup", "q": 4, "u": "tbsp"}]'::jsonb,'["Stir the flour, baking powder, sugar and salt together in a bowl.", "In a jug, beat the egg with the milk and the melted butter.", "Pour the wet into the dry and stir with a fork just until it comes together. It should still look slightly lumpy. Over-mixing makes the flour go stretchy and the crumpets tough — lumps are fine and will cook out.", "Let the batter rest 10 minutes. It thickens and the baking powder gets going, which is what gives you a proper puff.", "Heat a non-stick pan over medium-low heat. Too hot and they go dark brown outside while staying raw in the middle — this is the mistake everyone makes.", "Drop tablespoons of batter into the dry pan, leaving space between them. They spread to about 7 cm.", "Cook 2 minutes, until bubbles rise to the surface and POP, leaving little holes that stay open, and the edges look dry. That is the signal to turn.", "Flip and cook 1 minute more. They should be evenly golden, not patchy.", "Stack on a plate under a tea towel while you do the rest. Serve hot with butter melting into them and golden syrup poured over."]'::jsonb,'Waiting for the bubbles to pop before flipping is the whole technique. Flip too early and they collapse.'),
('stovetop-popcorn','Stovetop popcorn','🍿','snack',4,10,t,'[{"c": "pantry", "n": "Popping corn", "q": 100, "u": "g"}, {"c": "pantry", "n": "Cooking oil", "q": 3, "u": "tbsp"}, {"c": "dairy", "n": "Butter", "q": 40, "u": "g"}, {"c": "spices", "n": "Salt", "q": 1, "u": "tsp"}]'::jsonb,'["Use a large pot with a lid — the corn expands to about 40 times its size, so a small pot will overflow.", "Put the oil and exactly 3 kernels of corn in the pot, lid on, over medium-high heat.", "Wait for those 3 kernels to pop. That is your thermometer: it tells you the oil is at the right temperature without guessing.", "Take the pot off the heat, add the rest of the corn in one layer, put the lid back on and count to 30. This lets every kernel come up to the same temperature so they pop together instead of half burning while the rest catch up.", "Back on the heat. It will start popping within a minute. Shake the pot across the burner every few seconds, keeping the lid on but tilted very slightly to let steam escape — trapped steam makes soggy popcorn.", "Listen rather than look. When the pops slow to about 2 seconds apart, take it straight off the heat. Waiting for the last kernel burns the batch.", "Melt the butter and pour it over, then add the salt and toss well.", "Toss with your hands rather than a spoon to get the butter and salt everywhere without crushing it."]'::jsonb,'A quarter of the price of microwave popcorn and better. Cinnamon sugar instead of salt turns it into pudding.'),
('yoghurt-granola-cup','Yoghurt, granola & honey cup','🍨','snack',2,5,t,'[{"c": "dairy", "n": "Double cream yoghurt", "q": 400, "u": "g"}, {"c": "pantry", "n": "Granola", "q": 100, "u": "g"}, {"c": "pantry", "n": "Honey", "q": 2, "u": "tbsp"}, {"c": "veg", "n": "Berries or banana", "q": 150, "u": "g"}]'::jsonb,'["Slice the banana, or rinse the berries and pat them dry.", "Spoon a third of the yoghurt into the bottom of two glasses or bowls.", "Add a layer of granola, then a layer of fruit.", "Repeat: yoghurt, granola, fruit, finishing with granola on top so it stays crunchy.", "Drizzle the honey over the top just before eating. Adding it earlier soaks the granola and you lose the crunch, which is the only reason to layer it at all.", "Eat straight away. If you want it for tomorrow, build it in a jar but keep the granola in a separate bag and add it in the morning."]'::jsonb,'Five minutes and no cooking. The one snack in here that is also a decent breakfast.')
